// "At 19th level, a fighter gains DR 5/-- whenever he is wearing armor or
// using a shield." This is a genuinely new named class feature (NOT another
// Armor Training rank -- the PF1 Core Rulebook names no fifth Armor
// Training rank, and Armor Mastery is a distinct feature from the Armor
// Training pillar). Grounded as a bounded flat-magnitude record only,
// mirroring exactly how the Barbarian's own Damage Reduction class feature
// was grounded: no damage-resolution engine and no incoming-damage total
// exists anywhere in this codebase to apply it, and no
// worn-armor-or-shield condition check is computed, so this grounds no
// actual damage reduction.
const FIGHTER_ARMOR_MASTERY_LEVEL: u8 = 19;
const ARMOR_MASTERY_DAMAGE_REDUCTION: i16 = 5;

// Fighter Weapon Mastery, gained at level 20 (SD18 widening, the Fighter
// capstone -- the FINAL level within PF1's 1-20 character-level cap).
// Verified independently against d20pfsrd.com/classes/core-classes/fighter/
// and aonprd.com/ClassDisplay.aspx?ItemName=Fighter (byte-for-byte
// agreement): "At 20th level, a fighter chooses one weapon, such as the
// longsword, greataxe, or longbow. Any attacks made with that weapon
// automatically confirm all critical threats and have their damage
// multiplier increased by 1 (x2 becomes x3, for example). In addition, he
// cannot be disarmed while wielding a weapon of this type." This is a
// genuinely new named class feature. Grounded as a bounded grant-only
// identity/magnitude record only, mirroring exactly how the Fighter's own
// Armor Mastery class feature was grounded: no critical-hit-confirmation
// engine, no damage-multiplier-application engine, and no
// disarm-resolution engine exists anywhere in this codebase to apply it,
// so this grounds no actual automatic-critical-confirmation, no actual
// damage-multiplier change, and no actual disarm immunity.
const FIGHTER_WEAPON_MASTERY_LEVEL: u8 = 20;
const WEAPON_MASTERY_CRITICAL_MULTIPLIER_INCREASE: i16 = 1;

// Fighter Bravery, gained at level 2 with an additional +1 every four Fighter
// levels thereafter (level 6, level 10, ...): +1 Will save vs fear at level 2,
// +2 at level 6, +3 at level 10, per PF1 Core Rulebook. This slice grounds only
// the flat bonus magnitude as a standalone explanation record, mirroring the
// Weapon Training attack-bonus-rank idiom; no fear-condition or save-resolution
// engine exists anywhere in this codebase, so the bonus is never folded into the
// unconditional Will save total.
const FIGHTER_BRAVERY_LEVEL: u8 = 2;
const FIGHTER_BRAVERY_RANK_LEVEL_STRIDE: u8 = 4;

/// Simple integrated status for the GE-06 pilot headless receipt: whether the
/// path produced computed evidence or is blocked. This distinguishes evidence
/// from a blocker posture; it is not an oracle-checked parity verdict.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HeadlessReceiptStatus {
    /// The integrated deterministic path produced computed evidence with no
    /// claim-blocking diagnostics.
    Computed,
    /// The integrated deterministic path is blocked; at least one claim-blocking
    /// diagnostic is present and no success state is fabricated.
    Blocked,
}

/// One bounded, library-first, headless receipt for the accepted deterministic
/// GE-06 pilot path. It preserves case and source-package identity, a simple
/// computed/blocked status, and the full underlying computation (already-grounded
/// outputs, explanations, and diagnostics) for later parity or UI consumers.
///
/// This is headless computed evidence only; it must not be relabeled as
/// oracle-checked parity.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PilotHeadlessReceipt {
    /// Case identity carried from the loaded input (absent when the input names none).
    pub case_id: Option<String>,
    /// Source package identity carried from the loaded input.
    pub source_package_id: String,
    /// Whether the integrated path produced evidence or is blocked.
    pub status: HeadlessReceiptStatus,
    /// The underlying pilot computation, preserving the already-grounded outputs,
    /// explanation records, and claim-blocking diagnostics unchanged.
    pub computation: PilotBaseChassisComputation,
}

/// Build the GE-06 pilot headless receipt from a loaded character input.
///
/// This runs the existing deterministic compute surface and wraps it in one
/// bounded receipt shape, deriving the integrated status from the computation's
/// claim-blocking diagnostics: any claim-blocking diagnostic blocks the path,
/// otherwise the path is computed. It adds no new computed value, fabricates no
/// success state, and discards none of the existing explanations or diagnostics.
pub fn build_pilot_headless_receipt(input: &CharacterInput) -> PilotHeadlessReceipt {
    let computation = compute_pilot_base_chassis(input);

    let status = if computation.diagnostics.iter().any(|d| d.claim_blocking) {
        HeadlessReceiptStatus::Blocked
    } else {
        HeadlessReceiptStatus::Computed
    };

    PilotHeadlessReceipt {
        case_id: input.case_id.clone(),
        source_package_id: input.source_package_id.clone(),
        status,
        computation,
    }
}

/// Compute the GE-06 pilot base chassis from a loaded character input.
pub fn compute_pilot_base_chassis(input: &CharacterInput) -> PilotBaseChassisComputation {
    let mut explanations = Vec::new();
    let mut diagnostics = Vec::new();

    let ability_scores_for_modifiers = apply_human_ability_bonus(input, &mut explanations);
    let base_ability_modifiers =
        compute_ability_modifiers(&ability_scores_for_modifiers, &mut explanations);
    // v0.6 alpha swarm, risks item 8: Barbarian Rage's Strength/Constitution
    // morale bonus layers onto the base modifiers here (mirrors
    // `compute_total_saves`'s existing feat-bonus layering pattern), so
    // every downstream consumer of `ability_modifiers` (combat baseline,
    // total saves, selected-skill modifiers) sees the boosted values while
    // actively raging. The rage-rounds-per-day budget check itself uses the
    // separate `base_ability_modifiers` (pre-rage Constitution), since PF1's
    // rounds-per-day is derived from the character's normal Constitution,
    // not a value that depends on already being raged.
    let ability_modifiers_after_rage =
        apply_rage_ability_bonuses(base_ability_modifiers, input, &mut explanations);
    // v0.6 alpha swarm, risks item 8 (first APG/ACG closure): Skald Inspired
    // Rage's Strength/Constitution morale bonus layers on immediately after
    // Barbarian's, the identical shape -- class-ownership-gated by
    // `active_skald_inspired_rage_bonus` construction, so a non-Skald
    // character (which includes every Barbarian) sees no change here.
    let ability_modifiers_after_inspired_rage = apply_skald_inspired_rage_ability_bonuses(
        ability_modifiers_after_rage,
        input,
        &mut explanations,
    );
    // v0.6 alpha swarm, risks item 8 (second APG/ACG closure): Bloodrager
    // Bloodrage's Strength/Constitution morale bonus layers on next, the
    // identical shape -- class-ownership-gated by
    // `active_bloodrager_bloodrage_bonus` construction, so a non-Bloodrager
    // character sees no change here.
    let ability_modifiers_after_bloodrage = apply_bloodrager_bloodrage_ability_bonuses(
        ability_modifiers_after_inspired_rage,
        input,
        &mut explanations,
    );
    // v0.6 alpha swarm, risks item 8 (Alchemist Mutagen closure): Mutagen's
    // ability-score bonus/penalty layers on last, the identical
    // "apply on top of the chain" shape -- class-ownership-gated by
    // `active_alchemist_mutagen_bonus` construction, so a non-Alchemist
    // character sees no change here.
    let ability_modifiers = apply_alchemist_mutagen_ability_bonuses(
        ability_modifiers_after_bloodrage,
        input,
        &mut explanations,
    );

    let (base_attack_bonus, base_saves) =
        compute_class_chassis(input, &ability_modifiers, &mut explanations, &mut diagnostics)
            .unwrap_or_else(|| {
            diagnostics.push(ComputationDiagnostic {
                id: "class_chassis.unsupported".to_owned(),
                message: format!(
                    "base class chassis is only supported for a single-class {FIGHTER_CLASS_ID} \
                     at levels 1-{MAX_SUPPORTED_FIGHTER_LEVEL} or a single-class \
                     {WIZARD_CLASS_ID} at levels 1-{MAX_SUPPORTED_WIZARD_LEVEL}; chosen class \
                     levels {:?} do not provide it (either a multiclass mix, deferred to Epic 7, \
                     or a class this per-class dispatch does not yet recognize), so no chassis \
                     values were computed",
                    input.chosen.class_levels
                ),
                claim_blocking: true,
            });
            (0, BaseSaves::default())
        });

    let (baseline_melee_attack_bonus, baseline_armor_class) = compute_combat_baseline(
        input,
        &ability_modifiers,
        base_attack_bonus,
        &mut explanations,
        &mut diagnostics,
    );

    let total_saves = compute_total_saves(
        input,
        &ability_modifiers,
        &base_saves,
        &mut explanations,
        &mut diagnostics,
    );

    let selected_skill_modifiers = compute_selected_skill_modifiers(
        input,
        &ability_modifiers,
        &mut explanations,
        &mut diagnostics,
    );

    // v0.6 alpha swarm: standalone feat-derived skill facts (turnkey
    // consumer wiring for `feat_effects::standalone_skill_facts_from_feats`/
    // `skill_focus_facts_from_choices`, both already built and tested).
    // Unconditional on class ownership/posture -- these are general feat
    // effects, not class-specific, so they ground for every character
    // regardless of chassis support.
    ground_standalone_feat_skill_facts(input, &mut explanations);
    ground_orphan_feat_facts(input, &mut explanations);

    explain_fighter_class_features(input, &mut explanations);

    explain_fighter_level1_hit_points(input, &ability_modifiers, &mut explanations);

    explain_fighter_favored_class_bonus_choice(input, &mut explanations);

    explain_hybrid_level1_chassis(input, &mut explanations, &mut diagnostics);
    explain_barbarian_level1_chassis(
        input,
        &base_ability_modifiers,
        &mut explanations,
        &mut diagnostics,
    );
    explain_monk_level1_chassis(
        input,
        &ability_modifiers,
        &mut explanations,
        &mut diagnostics,
    );
    explain_rogue_level1_chassis(input, &mut explanations);


    // SD13-E3/E4/E5 Paladin-only decomposition: split the F6 hybrid class-feature
    // and spell-burden blockers into per-burden diagnostics so the chassis
    // burden is separable from the partial-caster spell burden on the runtime
    // path, widened by SD13-E5 to the level-2 lay on hands / divine grace
    // grant. This is an extension, never a downgrade, of the F6 surface.
    explain_paladin_level1_chassis_and_spell_burden_separation(
        input,
        &ability_modifiers,
        &mut explanations,
        &mut diagnostics,
    );

    // SD13-E3 Ranger-only decomposition: split the F6 Ranger non-spell
    // class-feature blocker into three named pillars, and ground Track and
    // combat style for real (Track as a bounded flat numeric value, combat
    // style as a level-gate absence record). This is an extension, never a
    // downgrade, of the F6 surface, mirroring the Paladin decomposition
    // immediately above.
    explain_ranger_level1_chassis_and_class_feature_separation(
        input,
        &ability_modifiers,
        &mut explanations,
        &mut diagnostics,
    );

    explain_sorcerer_level1_spell_baseline(
        input,
        &ability_modifiers,
        &mut explanations,
        &mut diagnostics,
    );

    explain_wizard_level1_prepared_spell_baseline(
        input,
        &ability_modifiers,
        &mut explanations,
        &mut diagnostics,
    );

    explain_cleric_level1_spell_baseline(
        input,
        &ability_modifiers,
        &mut explanations,
        &mut diagnostics,
    );

    explain_druid_level1_spell_baseline(
        input,
        &ability_modifiers,
        &mut explanations,
        &mut diagnostics,
    );

    explain_bard_level1_spell_baseline(
        input,
        &ability_modifiers,
        &mut explanations,
        &mut diagnostics,
    );

    explain_human_pilot_race_seam(input, &ability_modifiers, &mut explanations, &mut diagnostics);

    explain_human_trait_bundle(input, &mut explanations, &mut diagnostics);

    explain_dwarf_race_seam(input, &mut explanations, &mut diagnostics);

    explain_elf_race_seam(input, &mut explanations, &mut diagnostics);

    explain_gnome_race_seam(input, &mut explanations, &mut diagnostics);

    explain_half_elf_race_seam(
        input,
        &ability_modifiers,
        &mut explanations,
        &mut diagnostics,
    );

    explain_half_orc_race_seam(
        input,
        &ability_modifiers,
        &mut explanations,
        &mut diagnostics,
    );

    explain_halfling_race_seam(input, &mut explanations, &mut diagnostics);

    validate_fighter_feat_choice_legality(input, &mut diagnostics);

    PilotBaseChassisComputation {
        ability_modifiers,
        base_attack_bonus,
        base_saves,
        baseline_melee_attack_bonus,
        baseline_armor_class,
        total_saves,
        selected_skill_modifiers,
        explanations,
        diagnostics,
    }
}

/// Apply the Human ability-bonus choice's PF1 Core Rulebook +2 racial adjustment
/// to the targeted ability BEFORE ability modifiers are derived, and record the
/// real arithmetic (base score, racial bonus, adjusted score) as an audit trail.
///
/// Gated strictly on `race:human` plus a resolved `choice:human_ability_bonus`
/// selection. Every other race's chosen ability scores pass through completely
/// unchanged here: Dwarf, Elf, Gnome, Half-Elf, Half-Orc, and Halfling fixtures
/// all rely on the opposite, already-documented convention (see
/// `explain_dwarf_race_seam` and `explain_half_elf_race_seam`) that the chosen
/// score already bakes in their fixed/chosen racial adjustment, so applying any
/// further arithmetic to their scores here would double-count the bonus. Human's
/// own deterministic pilot fixture and the real PCGen oracle both confirm Human
/// is the one race whose chosen score is the PRE-bonus base — see the CG-03
/// follow-up receipt for the oracle evidence.
/// `pub` (rather than private) so this crate's own `contract.rs` (task 5's
/// encumbrance wiring) and the downstream `apps/desktop/src-tauri` crate's
/// `character_hub.rs` (item 2's durability wiring -- a separate crate,
/// where `pub(crate)` would not reach) can both derive the character's
/// real *effective* ability scores (post-racial-bonus) without re-deriving
/// this same Human-bonus arithmetic a second time, or falling back to the
/// pre-bonus raw scores, which would be wrong for a Human whose chosen
/// ability-bonus target is the relevant ability.
pub fn apply_human_ability_bonus(
    input: &CharacterInput,
    explanations: &mut Vec<ComputationExplanation>,
) -> AbilityScores {
    let scores = input.chosen.ability_scores.clone();

    if input.chosen.race_id != HUMAN_RACE_ID {
        return scores;
    }

    let Some(selection) = choice_selection(input, HUMAN_ABILITY_BONUS_CHOICE_ID) else {
        return scores;
    };

    let ability = selection
        .strip_prefix(ABILITY_SELECTION_PREFIX)
        .unwrap_or(selection)
        .to_owned();

    let Some(base_score) = ability_score_for(&scores, &ability) else {
        // An unrecognized ability target names nothing to adjust; leave scores
        // untouched rather than fabricating an adjustment.
        return scores;
    };

    let adjusted_score = base_score + HUMAN_ABILITY_BONUS_MAGNITUDE;
    let scores = with_ability_score(scores, &ability, adjusted_score);

    explanations.push(ComputationExplanation {
        id: "race.human.ability_bonus_applied".to_owned(),
        value: adjusted_score,
        detail: format!(
            "Human ability-bonus selection ({HUMAN_ABILITY_BONUS_CHOICE_ID} -> {selection}) applies \
             the PF1 Core Rulebook Standard Human +2 racial bonus to {ability} BEFORE ability \
             modifiers are derived: base chosen score {base_score} + \
             {HUMAN_ABILITY_BONUS_MAGNITUDE} racial = {adjusted_score}. This differs from \
             Dwarf/Half-Elf/etc., whose fixtures pre-bake their own racial adjustment into the \
             chosen score itself (no arithmetic performed on those seams); Human's chosen score \
             is confirmed PRE-bonus by both the deterministic pilot fixture and the real PCGen \
             oracle output."
        ),
    });

    scores
}

/// Look up the chosen score for a named ability. Unknown ability names yield
/// `None` rather than fabricating a value.
fn ability_score_for(scores: &AbilityScores, ability: &str) -> Option<i16> {
    match ability {
        "strength" => Some(scores.strength),
        "dexterity" => Some(scores.dexterity),
        "constitution" => Some(scores.constitution),
        "intelligence" => Some(scores.intelligence),
        "wisdom" => Some(scores.wisdom),
        "charisma" => Some(scores.charisma),
        _ => None,
    }
}

/// Return a copy of `scores` with the named ability's score replaced. Unknown
/// ability names return `scores` unchanged rather than fabricating a field.
fn with_ability_score(mut scores: AbilityScores, ability: &str, new_score: i16) -> AbilityScores {
    match ability {
        "strength" => scores.strength = new_score,
        "dexterity" => scores.dexterity = new_score,
        "constitution" => scores.constitution = new_score,
        "intelligence" => scores.intelligence = new_score,
        "wisdom" => scores.wisdom = new_score,
        "charisma" => scores.charisma = new_score,
        _ => {}
    }
    scores
}

fn compute_ability_modifiers(
    scores: &AbilityScores,
    explanations: &mut Vec<ComputationExplanation>,
) -> AbilityModifiers {
    let abilities = [
        ("strength", scores.strength),
        ("dexterity", scores.dexterity),
        ("constitution", scores.constitution),
        ("intelligence", scores.intelligence),
        ("wisdom", scores.wisdom),
        ("charisma", scores.charisma),
    ];

    let mut modifiers = AbilityModifiers::default();
    for (ability, score) in abilities {
        let modifier = ability_modifier(score);
        explanations.push(ComputationExplanation {
            id: format!("ability_modifier.{ability}"),
            value: modifier,
            detail: format!(
                "{ability} ability modifier from chosen score {score}: floor({score} / 2) - 5 = {modifier}"
            ),
        });
        assign_modifier(&mut modifiers, ability, modifier);
    }

    modifiers
}

/// Applies Barbarian Rage's Strength/Constitution morale bonus to `base`
/// when a valid, active, in-budget Rage activation is present for this
/// character (v0.6 alpha swarm, risks item 8). Mirrors `compute_total_saves`'s
/// existing pattern of layering `feat_effects::save_bonuses_from_feats`'s
/// separately-computed result onto a base total, rather than baking this
/// into `compute_ability_modifiers` itself -- `compute_ability_modifiers` is
/// called for every class, every request, and stays completely untouched.
/// Class-ownership-gated by construction: `active_barbarian_rage_bonus` only
/// returns `Some` when `class_levels` actually contains Barbarian, so a
/// non-Barbarian character's stray `class_ability_activations` entry for
/// `BARBARIAN_RAGE_ABILITY_ID` is never read at all.
///
/// The Strength/Constitution ability-SCORE bonus (+4/+6/+8, always even)
/// becomes exactly half that as an ability-MODIFIER bonus (+2/+3/+4):
/// modifier = floor((score - 10) / 2), and adding an even N to score adds
/// exactly N/2 to the floored modifier regardless of the original score's
/// parity.
fn apply_rage_ability_bonuses(
    base: AbilityModifiers,
    input: &CharacterInput,
    explanations: &mut Vec<ComputationExplanation>,
) -> AbilityModifiers {
    let Some((barbarian_level, strength_bonus, constitution_bonus, will_save_bonus, rage_source_feature)) =
        active_barbarian_rage_bonus(input, &base)
    else {
        return base;
    };

    let strength_modifier_bonus = strength_bonus / 2;
    let constitution_modifier_bonus = constitution_bonus / 2;
    let boosted = AbilityModifiers {
        strength: base.strength + strength_modifier_bonus,
        constitution: base.constitution + constitution_modifier_bonus,
        ..base
    };
    explanations.push(ComputationExplanation {
        id: "ability_modifier.barbarian.rage_bonus_applied".to_owned(),
        value: strength_modifier_bonus,
        detail: format!(
            "Barbarian level {barbarian_level} {rage_source_feature} applied to ability \
             modifiers: +{strength_bonus} Strength / +{constitution_bonus} Constitution morale \
             bonus (ability score) is +{strength_modifier_bonus} Strength modifier / \
             +{constitution_modifier_bonus} Constitution modifier (an even score bonus always \
             halves exactly onto the floored modifier). Applied only while actively, validly \
             raging; the Will-save bonus (+{will_save_bonus}) is layered onto compute_total_saves \
             separately, and the {BARBARIAN_RAGE_ARMOR_CLASS_PENALTY} Armor Class penalty onto \
             compute_combat_baseline separately"
        ),
    });
    boosted
}

/// Pathfinder ability modifier: `floor(score / 2) - 5`. `div_euclid` gives true
/// floor division so negative scores would round down rather than toward zero.
/// `pub` (rather than private) so `apps/desktop/src-tauri`'s
/// `character_hub.rs` durability commands (v0.6 alpha swarm, item 2, a
/// separate downstream crate -- `pub(crate)` would not reach it) can derive
/// the real Constitution modifier from an effective ability score without
/// re-deriving this same formula a second time.
pub fn ability_modifier(score: i16) -> i16 {
    score.div_euclid(2) - 5
}

fn assign_modifier(modifiers: &mut AbilityModifiers, ability: &str, modifier: i16) {
    match ability {
        "strength" => modifiers.strength = modifier,
        "dexterity" => modifiers.dexterity = modifier,
        "constitution" => modifiers.constitution = modifier,
        "intelligence" => modifiers.intelligence = modifier,
        "wisdom" => modifiers.wisdom = modifier,
        "charisma" => modifiers.charisma = modifier,
        _ => unreachable!("ability set is fixed and fully matched"),
    }
}

/// Make the already-grounded Human pilot race seam explicit instead of leaving it an
/// incidental side effect of the numeric outputs.
///
/// This adds no new computed mechanic and no new input surface. It derives strictly
/// from existing chosen input — the `race:human` identity and the named
/// `choice:human_ability_bonus` and `choice:human_bonus_feat` selections — and from the
/// already-computed deterministic outputs — the ability modifiers and the grounded
/// Dodge armor-class contribution. It thereby surfaces the named Human ability-bonus and
/// bonus-feat interaction pressure as legible explanation records.
///
/// This function handles only the `race:human` branch of `explain_race_seam`;
/// non-Human routing (the bounded Half-Elf diagnostic and the
/// `race.semantics.unverified` catch-all) lives in the dispatcher. This slice
/// grounds no broader Human racial trait burden (size, speed, senses, extra
/// skill ranks).
fn explain_human_pilot_race_seam(
    input: &CharacterInput,
    ability_modifiers: &AbilityModifiers,
    explanations: &mut Vec<ComputationExplanation>,
    diagnostics: &mut Vec<ComputationDiagnostic>,
) {
    if input.chosen.race_id != HUMAN_RACE_ID {
        // Dwarf, Elf, Gnome, Half-Elf, Half-Orc, and Halfling carry their own
        // dedicated race-semantics seams (explain_dwarf_race_seam,
        // explain_elf_race_seam, explain_gnome_race_seam,
        // explain_half_elf_race_seam, explain_half_orc_race_seam,
        // explain_halfling_race_seam); they replace this generic diagnostic
        // rather than stacking alongside it. With Halfling landed, this branch
        // is unreachable for the seven-race SD-13 roster but stays as a
        // defensive fallback for any race identity outside that roster.
        if input.chosen.race_id != DWARF_RACE_ID
            && input.chosen.race_id != ELF_RACE_ID
            && input.chosen.race_id != GNOME_RACE_ID
            && input.chosen.race_id != HALF_ELF_RACE_ID
            && input.chosen.race_id != HALF_ORC_RACE_ID
            && input.chosen.race_id != HALFLING_RACE_ID
        {
            diagnostics.push(ComputationDiagnostic {
                id: "race.semantics.unverified".to_owned(),
                message: format!(
                    "race semantics are grounded only for {HUMAN_RACE_ID} on the deterministic pilot seam; \
                     chosen race {} has no grounded race semantics in this slice",
                    input.chosen.race_id
                ),
                claim_blocking: false,
            });
        }
        return;
    }

    // Human ability-bonus interaction: the named choice targets one ability. The
    // +2 racial adjustment was already applied to that ability's score BEFORE
    // ability modifiers were derived (see `apply_human_ability_bonus` and its
    // `race.human.ability_bonus_applied` explanation for the base-score
    // arithmetic). This record narrates the already-adjusted result only; it
    // performs no further arithmetic and does not re-apply the bonus.
    if let Some(selection) = choice_selection(input, HUMAN_ABILITY_BONUS_CHOICE_ID) {
        let ability = selection
            .strip_prefix(ABILITY_SELECTION_PREFIX)
            .unwrap_or(selection);
        let modifier = ability_modifier_for(ability_modifiers, ability);
        explanations.push(ComputationExplanation {
            id: "race.human.ability_bonus_target".to_owned(),
            value: modifier,
            detail: format!(
                "Human ability-bonus selection ({HUMAN_ABILITY_BONUS_CHOICE_ID} -> {selection}) targets \
                 {ability}; the racial-bonus-adjusted {ability} score (base chosen score + the +2 Human \
                 racial bonus, applied before ability modifiers were derived) yields modifier {modifier:+}"
            ),
        });
    }

    // Human bonus-feat interaction: the named choice grants a feat. Surface the grounded
    // Dodge armor-class contribution the deterministic baseline already relies on.
    if let Some(selection) = choice_selection(input, HUMAN_BONUS_FEAT_CHOICE_ID) {
        let (value, detail) = if selection == DODGE_FEAT_ID {
            (
                DODGE_AC_BONUS,
                format!(
                    "Human bonus-feat selection ({HUMAN_BONUS_FEAT_CHOICE_ID} -> {selection}) grants Dodge, \
                     the deterministic Dodge feat contributing {DODGE_AC_BONUS:+} to the baseline armor class"
                ),
            )
        } else {
            (
                0,
                format!(
                    "Human bonus-feat selection ({HUMAN_BONUS_FEAT_CHOICE_ID} -> {selection}) is a named Human \
                     bonus feat, but only the deterministic Dodge grant has a grounded computed contribution"
                ),
            )
        };
        explanations.push(ComputationExplanation {
            id: "race.human.bonus_feat_grant".to_owned(),
            value,
            detail,
        });
    }

    // Bounded honesty: only the named seam is grounded. This is explicit but
    // non-claim-blocking so the deterministic pilot still reports computed evidence.
    diagnostics.push(ComputationDiagnostic {
        id: "race.human.bounded_semantics".to_owned(),
        message: "Human race semantics are grounded for the deterministic pilot's named \
                  ability-bonus and bonus-feat selections, and the SD13-E6-F3a trait bundle \
                  (size, speed, senses, extra skill ranks) is classified explicitly; the \
                  remaining PF1 Standard Human racial trait surface (alternate Human racial \
                  traits, variant Humans, half-Human heritages, and any ruleset-level effects \
                  outside the named deterministic pilot) remains unverified"
            .to_owned(),
        claim_blocking: false,
    });
}

const DWARF_RACE_ID: &str = "race:dwarf";
const DWARF_SIZE_CATEGORY: &str = "Medium";
const DWARF_BASE_SPEED_FEET: i16 = 20;
const DWARF_DARKVISION_FEET: i16 = 60;
const DWARF_CON_ADJUSTMENT: i16 = 2;
const DWARF_CHA_ADJUSTMENT: i16 = -2;
/// v0.6 alpha swarm (QA-found systemic parity gap, same shape as Elf's
/// missing +2 Intelligence): verified against the real PCGen corpus,
/// `core_essentials/races/dwarf/dwarf_abilities_race.lst:18`'s "Dwarf
/// Racial Default" ability-score row (not an alternate) --
/// `BONUS:STAT|CON,WIS|2|TYPE=Racial`, `BONUS:STAT|CHA|-2|TYPE=Racial`: +2
/// Constitution, +2 Wisdom, -2 Charisma. This engine only grounded CON/CHA;
/// Wisdom was missing entirely, not even flagged as an alternate.
const DWARF_WIS_ADJUSTMENT: i16 = 2;
/// PF1 Core Rulebook Dwarf Stonecunning flat Perception situational-bonus
/// magnitude (verified against `dwarf_abilities_race.lst:27`'s
/// `BONUS:SITUATION|Perception=to notice unusual stonework|2|TYPE=Racial`
/// and `dwarf_skills.lst:6`'s `Perception.MOD SITUATION:to notice unusual
/// stonework`). Distinct from the separate Greed (Appraise) racial trait.
const DWARF_STONECUNNING_PERCEPTION_BONUS: i16 = 2;
/// PF1 Core Rulebook Dwarf Greed flat Appraise situational-bonus magnitude
/// (verified against `dwarf_abilities_race.lst:23`'s
/// `BONUS:SITUATION|Appraise=to assess nonmagical metals or gemstones|2|TYPE=Racial`
/// and `dwarf_skills.lst:5`'s `Appraise.MOD SITUATION:to assess nonmagical
/// metals or gemstones`). Distinct from the already-grounded Stonecunning
/// (Perception) racial trait.
const DWARF_GREED_APPRAISE_BONUS: i16 = 2;
/// PF1 Core Rulebook Dwarf Hardy flat racial saving-throw-bonus magnitude
/// against poison, spells, and spell-like abilities (verified against
/// `dwarf_abilities_race.lst:25`'s
/// `BONUS:VAR|SaveBonus_vs_Poison|2|TYPE=Racial` and
/// `BONUS:VAR|SaveBonus_vs_Spells|2|TYPE=Racial`). Both save categories
/// share the same flat +2 magnitude, mirroring the already-grounded Elf
/// Elven Immunities enchantment-save-bonus idiom.
const DWARF_HARDY_SAVE_BONUS: i16 = 2;
/// PF1 Core Rulebook Dwarf Stability flat racial Combat Maneuver Defense
/// bonus magnitude against bull rush and trip attempts made while the Dwarf
/// is standing on the ground (verified against
/// `dwarf_abilities_race.lst:26`'s
/// `BONUS:VAR|CMD_BullRush,CMD_Trip|4|TYPE=Racial`). Both maneuver
/// categories share the same flat +4 magnitude, mirroring the already-
/// grounded Dwarf Hardy two-save-category flat-bonus idiom exactly.
const DWARF_STABILITY_CMD_BONUS: i16 = 4;
/// PF1 Core Rulebook Dwarf Defensive Training flat racial dodge-bonus-to-AC
/// magnitude against monsters of the giant subtype (verified against
/// `dwarf_abilities_race.lst:22`'s
/// `BONUS:VAR|RacialDefensiveTrainingBonus|4`). A single flat magnitude
/// applied to a single named derived-stat target, mirroring the already-
/// grounded Dwarf Stability flat-bonus idiom exactly.
const DWARF_DEFENSIVE_TRAINING_DODGE_BONUS: i16 = 4;

/// SD13-E2 Dwarf racial trait bundle explanation seam (mirroring the SD13-E6-F3a
/// Human trait bundle pattern for the first non-Human core race), widened by the
/// SD18 dwarf-stonecunning, dwarf-greed, dwarf-hardy, dwarf-stability, and
/// dwarf-defensive-training cycles.
///
/// Surfaces nine grounded PF1 Core Rulebook Dwarf racial trait dimensions (ability
/// modifiers, size, speed, senses, Stonecunning, Greed, Hardy, Stability,
/// Defensive Training) as explicit `ComputationExplanation` records so the Dwarf
/// identity is legible on the runtime path rather than left behind the generic
/// `race.semantics.unverified` diagnostic every other non-Human race still receives.
///
/// This function:
///   - runs only when `race_id == race:dwarf`; every other race is unaffected
///     (Human keeps its own seam; every other non-Human race keeps the generic
///     `race.semantics.unverified` diagnostic from `explain_human_race_seam`),
///   - adds no new computed mechanical contribution beyond a flat, ungrounded-total
///     situational-bonus magnitude: the ability-modifiers record is recognition-only
///     (the chosen Constitution/Charisma scores are understood to already reflect
///     the fixed +2/-2 racial adjustment; no arithmetic is performed on this seam),
///     the size/senses records carry the grounded source value as identity only, and
///     the Stonecunning, Greed, Hardy, Stability, and Defensive Training records each
///     name only their own flat bonus magnitude (no Perception-check-total,
///     Appraise-check-total, stonework-detection, goods-valuation, saving-throw-total,
///     Combat-Maneuver-Defense-total, or Armor-Class-total engine exists),
///   - replaces the generic `race.semantics.unverified` diagnostic with a
///     Dwarf-specific `race.dwarf.bounded_semantics` note naming the still-unproven
///     families explicitly (Hatred, weapon familiarity, and the explicit absence of
///     any Dwarf racial bonus feat),
///   - is bounded to race recognition only; it deliberately grounds no Dwarf
///     class-chassis interaction, no other race, and no PF1 alternate ruleset.
fn explain_dwarf_race_seam(
    input: &CharacterInput,
    explanations: &mut Vec<ComputationExplanation>,
    diagnostics: &mut Vec<ComputationDiagnostic>,
) {
    if input.chosen.race_id != DWARF_RACE_ID {
        return;
    }

    // ----- ability modifiers -----
    // Recognition record only: PF1 Core Dwarf ability adjustments (+2 Con / -2 Cha)
    // are fixed, not a player choice. The chosen Constitution/Charisma scores are
    // understood to already reflect this adjustment; no arithmetic is performed here.
    explanations.push(ComputationExplanation {
        id: "race.dwarf.trait_bundle.ability_modifiers".to_owned(),
        value: 0,
        detail: format!(
            "Dwarf racial trait bundle — ability modifiers: PF1 Core Dwarf grants a fixed \
             {DWARF_CON_ADJUSTMENT:+} Constitution, {DWARF_WIS_ADJUSTMENT:+} Wisdom, and \
             {DWARF_CHA_ADJUSTMENT:+} Charisma racial adjustment (verified against the real \
             PCGen corpus: core_essentials/races/dwarf/dwarf_abilities_race.lst's \"Dwarf \
             Racial Default\" ability-score row — BONUS:STAT|CON,WIS|2|TYPE=Racial, \
             BONUS:STAT|CHA|-2|TYPE=Racial). This is a bounded recognition record naming the \
             fixed adjustment on the deterministic pilot seam; the chosen Constitution, Wisdom, \
             and Charisma scores are understood to already reflect it, so this record performs \
             no arithmetic and carries no fabricated mechanical value (+0)"
        ),
    });

    // ----- size -----
    explanations.push(ComputationExplanation {
        id: "race.dwarf.trait_bundle.size".to_owned(),
        value: 0,
        detail: format!(
            "Dwarf racial trait bundle — size: PF1 Core Dwarf is {DWARF_SIZE_CATEGORY} size \
             (cr_races.lst race:dwarf SIZE:MEDIUM). This is a bounded recognition record naming \
             the Dwarf size category on the deterministic pilot seam; it contributes no numeric \
             effect to attack rolls, AC, skill checks, ability checks, or any other computed \
             value, so it carries no fabricated mechanical value (+0)"
        ),
    });

    // ----- speed -----
    // Recognition record for the 20 ft base land speed. PF1 Core Dwarf speed is
    // never reduced by armor or encumbrance, unlike most Medium races; this is
    // named explicitly as identity only — no computed speed-derived value is
    // fabricated.
    explanations.push(ComputationExplanation {
        id: "race.dwarf.trait_bundle.speed".to_owned(),
        value: DWARF_BASE_SPEED_FEET,
        detail: format!(
            "Dwarf racial trait bundle — speed: PF1 Core Dwarf has a base land speed of \
             {DWARF_BASE_SPEED_FEET} ft that is never reduced by armor or encumbrance \
             (cr_races.lst race:dwarf GAIT:WALK|{DWARF_BASE_SPEED_FEET}). This is a grounded \
             recognition value carrying the Dwarf base-speed identity on the deterministic pilot \
             seam; it contributes no computed speed-derived effect to any chassis output, skill \
             modifier, attack roll, or combat baseline"
        ),
    });

    // ----- senses -----
    // Recognition record for Darkvision 60 ft, distinct from Human's bounded
    // no-special-senses classification.
    explanations.push(ComputationExplanation {
        id: "race.dwarf.trait_bundle.senses".to_owned(),
        value: DWARF_DARKVISION_FEET,
        detail: format!(
            "Dwarf racial trait bundle — senses: PF1 Core Dwarf grants Darkvision \
             {DWARF_DARKVISION_FEET} ft (cr_races.lst race:dwarf SENSE:Darkvision \
             ({DWARF_DARKVISION_FEET} ft)). This is a grounded recognition value carrying the \
             Dwarf Darkvision identity on the deterministic pilot seam; it contributes no \
             computed low-light or perception-derived effect to any chassis output"
        ),
    });

    // ----- Stonecunning (SD18 dwarf-stonecunning cycle) -----
    // Grounded flat +2 situational bonus on Perception checks to potentially
    // notice unusual stonework, such as traps and hidden doors located in
    // stone walls or floors (core_essentials/races/dwarf/dwarf_abilities_race.lst:27
    // BONUS:SITUATION|Perception=to notice unusual stonework|2|TYPE=Racial;
    // dwarf_skills.lst:6 Perception.MOD SITUATION:to notice unusual
    // stonework). Mirrors the existing flat skill-bonus-magnitude idiom used
    // elsewhere on this seam (e.g. Bard Inspire Competence, Ranger Track): no
    // Perception-check-total or stonework-detection engine exists anywhere in
    // this codebase, so this names only the flat situational-bonus magnitude,
    // not a check-execution engine. Distinct from Greed (a separate +2
    // Appraise racial trait for assessing nonmagical precious-metal/gemstone
    // goods), which remains unground.
    explanations.push(ComputationExplanation {
        id: "race.dwarf.trait_bundle.stonecunning".to_owned(),
        value: DWARF_STONECUNNING_PERCEPTION_BONUS,
        detail: format!(
            "Dwarf racial trait bundle — Stonecunning: PF1 Core Dwarf grants a flat \
             {DWARF_STONECUNNING_PERCEPTION_BONUS:+} bonus on Perception checks to potentially \
             notice unusual stonework, such as traps and hidden doors located in stone walls or \
             floors (dwarf_abilities_race.lst:27 BONUS:SITUATION|Perception=to notice unusual \
             stonework|{DWARF_STONECUNNING_PERCEPTION_BONUS}|TYPE=Racial; dwarf_skills.lst:6 \
             Perception.MOD SITUATION:to notice unusual stonework). This is a bounded flat \
             situational-bonus-magnitude recognition record naming the Stonecunning identity on \
             the deterministic pilot seam; no Perception-check-total or stonework-detection \
             engine exists anywhere in this codebase, so no check resolution is fabricated from \
             this record"
        ),
    });

    // ----- Greed (SD18 dwarf-greed cycle) -----
    // Grounded flat +2 situational bonus on Appraise checks made to
    // determine the price of nonmagical goods that contain precious metals
    // or gemstones (core_essentials/races/dwarf/dwarf_abilities_race.lst:23
    // BONUS:SITUATION|Appraise=to assess nonmagical metals or gemstones|2|TYPE=Racial;
    // dwarf_skills.lst:5 Appraise.MOD SITUATION:to assess nonmagical metals
    // or gemstones). Mirrors the already-grounded Stonecunning flat
    // skill-bonus-magnitude idiom on this same seam: no
    // Appraise-check-total or goods-valuation engine exists anywhere in
    // this codebase, so this names only the flat situational-bonus
    // magnitude, not a check-execution engine.
    explanations.push(ComputationExplanation {
        id: "race.dwarf.trait_bundle.greed".to_owned(),
        value: DWARF_GREED_APPRAISE_BONUS,
        detail: format!(
            "Dwarf racial trait bundle — Greed: PF1 Core Dwarf grants a flat \
             {DWARF_GREED_APPRAISE_BONUS:+} bonus on Appraise checks made to determine the \
             price of nonmagical goods that contain precious metals or gemstones \
             (dwarf_abilities_race.lst:23 BONUS:SITUATION|Appraise=to assess nonmagical \
             metals or gemstones|{DWARF_GREED_APPRAISE_BONUS}|TYPE=Racial; \
             dwarf_skills.lst:5 Appraise.MOD SITUATION:to assess nonmagical metals or \
             gemstones). This is a bounded flat situational-bonus-magnitude recognition \
             record naming the Greed identity on the deterministic pilot seam; no \
             Appraise-check-total or goods-valuation engine exists anywhere in this \
             codebase, so no check resolution is fabricated from this record"
        ),
    });

    // ----- Hardy (SD18 dwarf-hardy cycle) -----
    // Bundles two distinct save categories, both grounded honestly, mirroring
    // the already-landed Elf Elven Immunities flat racial saving-throw-bonus
    // idiom exactly (applied to a save category instead of a skill):
    //   - a +2 racial saving throw bonus against poison
    //     (dwarf_abilities_race.lst:25 BONUS:VAR|SaveBonus_vs_Poison|2|TYPE=Racial);
    //   - a +2 racial saving throw bonus against spells and spell-like
    //     abilities (dwarf_abilities_race.lst:25
    //     BONUS:VAR|SaveBonus_vs_Spells|2|TYPE=Racial).
    // Both share the same flat magnitude, so this names only the flat
    // save-bonus magnitude, not a saving-throw-total engine: no
    // saving-throw-resolution engine exists anywhere in this codebase, so no
    // check resolution is fabricated from this record.
    explanations.push(ComputationExplanation {
        id: "race.dwarf.trait_bundle.hardy".to_owned(),
        value: DWARF_HARDY_SAVE_BONUS,
        detail: format!(
            "Dwarf racial trait bundle — Hardy: PF1 Core Dwarf grants a flat \
             {DWARF_HARDY_SAVE_BONUS:+} racial bonus on saving throws against poison, and a \
             flat {DWARF_HARDY_SAVE_BONUS:+} racial bonus on saving throws against spells and \
             spell-like abilities (dwarf_abilities_race.lst:25 \
             BONUS:VAR|SaveBonus_vs_Poison|{DWARF_HARDY_SAVE_BONUS}|TYPE=Racial, \
             BONUS:VAR|SaveBonus_vs_Spells|{DWARF_HARDY_SAVE_BONUS}|TYPE=Racial). This is a \
             bounded flat saving-throw-bonus-magnitude recognition record naming the Hardy \
             identity on the deterministic pilot seam, mirroring the already-grounded Elf \
             Elven Immunities enchantment-save-bonus idiom; no saving-throw-total engine \
             exists anywhere in this codebase, so no check resolution is fabricated from this \
             record"
        ),
    });

    // ----- Stability (SD18 dwarf-stability cycle) -----
    // Bundles two distinct combat-maneuver-defense categories, both grounded
    // honestly, mirroring the already-landed Dwarf Hardy flat racial-bonus
    // idiom exactly (a single flat magnitude applied to two named derived-
    // stat targets instead of two save categories):
    //   - a +4 racial bonus to Combat Maneuver Defense when resisting a bull
    //     rush attempt while standing on the ground
    //     (dwarf_abilities_race.lst:26 BONUS:VAR|CMD_BullRush|4|TYPE=Racial);
    //   - a +4 racial bonus to Combat Maneuver Defense when resisting a trip
    //     attempt while standing on the ground (dwarf_abilities_race.lst:26
    //     BONUS:VAR|CMD_Trip|4|TYPE=Racial).
    // Both share the same flat magnitude, so this names only the flat
    // CMD-bonus magnitude, not a Combat-Maneuver-Defense-total engine: no
    // such engine exists anywhere in this codebase, so no check resolution
    // is fabricated from this record.
    explanations.push(ComputationExplanation {
        id: "race.dwarf.trait_bundle.stability".to_owned(),
        value: DWARF_STABILITY_CMD_BONUS,
        detail: format!(
            "Dwarf racial trait bundle — Stability: PF1 Core Dwarf grants a flat \
             {DWARF_STABILITY_CMD_BONUS:+} racial bonus to Combat Maneuver Defense when \
             resisting a bull rush attempt, and a flat {DWARF_STABILITY_CMD_BONUS:+} racial \
             bonus to Combat Maneuver Defense when resisting a trip attempt, in both cases \
             while standing on the ground (dwarf_abilities_race.lst:26 \
             BONUS:VAR|CMD_BullRush,CMD_Trip|{DWARF_STABILITY_CMD_BONUS}|TYPE=Racial). This \
             is a bounded flat CMD-bonus-magnitude recognition record naming the Stability \
             identity on the deterministic pilot seam, mirroring the already-grounded Dwarf \
             Hardy two-save-category flat-bonus idiom; no Combat-Maneuver-Defense-total \
             engine exists anywhere in this codebase, so no check resolution is fabricated \
             from this record"
        ),
    });

    // ----- Defensive Training (SD18 dwarf-defensive-training cycle) -----
    // Grounded flat +4 dodge bonus to Armor Class against monsters of the
    // giant subtype (core_essentials/races/dwarf/dwarf_abilities_race.lst:22
    // BONUS:VAR|RacialDefensiveTrainingBonus|4). Mirrors the already-grounded
    // Dwarf Stability flat-bonus idiom on this same seam (a single flat
    // magnitude applied to a single named derived-stat target): no
    // Armor-Class-total or giant-subtype-detection engine exists anywhere in
    // this codebase, so this names only the flat dodge-bonus magnitude, not
    // a check-execution engine.
    explanations.push(ComputationExplanation {
        id: "race.dwarf.trait_bundle.defensive_training".to_owned(),
        value: DWARF_DEFENSIVE_TRAINING_DODGE_BONUS,
        detail: format!(
            "Dwarf racial trait bundle — Defensive Training: PF1 Core Dwarf grants a flat \
             {DWARF_DEFENSIVE_TRAINING_DODGE_BONUS:+} dodge bonus to Armor Class against \
             monsters of the giant subtype (dwarf_abilities_race.lst:22 \
             BONUS:VAR|RacialDefensiveTrainingBonus|{DWARF_DEFENSIVE_TRAINING_DODGE_BONUS}). \
             This is a bounded flat dodge-bonus-magnitude recognition record naming the \
             Defensive Training identity on the deterministic pilot seam, mirroring the \
             already-grounded Dwarf Stability flat-bonus idiom; no Armor-Class-total or \
             giant-subtype-detection engine exists anywhere in this codebase, so no check \
             resolution is fabricated from this record"
        ),
    });

    // Bounded honesty: nine named dimensions are now grounded (ability
    // modifiers, size, speed, senses, Stonecunning, Greed, Hardy, Stability,
    // Defensive Training). This replaces the generic
    // race.semantics.unverified diagnostic for Dwarf specifically and stays
    // non-claim-blocking so the deterministic pilot still reports computed
    // evidence.
    diagnostics.push(ComputationDiagnostic {
        id: "race.dwarf.bounded_semantics".to_owned(),
        message: "Dwarf race semantics are grounded for the deterministic pilot's ability \
                  modifiers, size, speed, senses, Stonecunning (flat +2 Perception \
                  situational bonus to notice unusual stonework), Greed (flat +2 \
                  Appraise situational bonus to assess nonmagical precious-metal/gemstone \
                  goods), Hardy (flat +2 racial bonus on saving throws against poison, \
                  spells, and spell-like abilities), Stability (flat +4 racial bonus to \
                  Combat Maneuver Defense against bull rush and trip attempts while standing \
                  on the ground), and Defensive Training (flat +4 dodge bonus to Armor Class \
                  against monsters of the giant subtype) trait bundle; the remaining PF1 \
                  Core Dwarf racial trait surface remains unverified: Hatred (bonus on \
                  attack rolls against orcs and goblinoids), and weapon familiarity \
                  (battleaxe, heavy pick, warhammer, dwarven waraxe, dwarven urgrosh). PF1 \
                  core Dwarves gain no racial bonus feat (unlike Human), so that family is \
                  explicitly not applicable rather than silently omitted."
            .to_owned(),
        claim_blocking: false,
    });
}

const ELF_RACE_ID: &str = "race:elf";
const ELF_SIZE_CATEGORY: &str = "Medium";
const ELF_BASE_SPEED_FEET: i16 = 30;
const ELF_DEX_ADJUSTMENT: i16 = 2;
const ELF_CON_ADJUSTMENT: i16 = -2;
/// v0.6 alpha swarm (QA-found real PCGen-parity gap): this record's own
/// detail text used to call +2 Intelligence "the alternate PF1 +2
/// Intelligence Elf variant... out of scope" -- checked against the real
/// PCGen corpus (not memory) and that framing was wrong. `cr_races.lst`'s
/// `Elf.MOD` is only a source-page citation; the real base race data lives
/// in a separate PCC pack, `elf_abilities_race.lst:18` (
/// `core_essentials/races/elf/elf_abilities_race.lst`), whose ability-score
/// row is explicitly typed `TYPE:...Elf Racial Default...` (not an
/// alternate/optional variant) and carries `BONUS:STAT|DEX,INT|2|TYPE=Racial`
/// alongside `BONUS:STAT|CON|-2|TYPE=Racial` -- +2 Intelligence is the
/// CRB-standard default, not an alternate. Matters now specifically because
/// Elf Wizard is a real reachable combination (v0.6 alpha swarm) and
/// Intelligence drives a Wizard's spell save DC and bonus spells, so
/// omitting it silently shorted an Elf Wizard's casting stat by 2.
const ELF_INT_ADJUSTMENT: i16 = 2;

/// SD13-E2 Elf racial trait bundle explanation seam (mirroring the Dwarf pattern
/// for the second non-Human core race).
///
/// Surfaces four grounded PF1 Core Rulebook Elf racial trait dimensions (ability
/// modifiers, size, speed, senses) as explicit `ComputationExplanation` records so
/// the Elf identity is legible on the runtime path rather than left behind the
/// generic `race.semantics.unverified` diagnostic every other non-Human race still
/// receives.
///
/// This function:
///   - runs only when `race_id == race:elf`; every other race is unaffected
///     (Human and Dwarf keep their own seams; every other non-Human race keeps
///     the generic `race.semantics.unverified` diagnostic),
///   - adds no new computed mechanical contribution: the ability-modifiers record
///     is recognition-only (the chosen Dexterity/Constitution scores are
///     understood to already reflect the fixed +2/-2 racial adjustment; no
///     arithmetic is performed on this seam), and the size/senses records carry
///     the grounded source value as identity only,
///   - replaces the generic `race.semantics.unverified` diagnostic with an
///     Elf-specific `race.elf.bounded_semantics` note naming the still-unproven
///     families explicitly (weapon familiarity, bonus languages, and the
///     explicit absence of any Elf racial bonus feat) now that Keen Senses
///     and Elven Immunities are both grounded,
///   - is bounded to race recognition only; it deliberately grounds no Elf
///     class-chassis interaction, no other race, no alternate +2 Intelligence
///     ability variant, and no PF1 alternate ruleset.
fn explain_elf_race_seam(
    input: &CharacterInput,
    explanations: &mut Vec<ComputationExplanation>,
    diagnostics: &mut Vec<ComputationDiagnostic>,
) {
    if input.chosen.race_id != ELF_RACE_ID {
        return;
    }

    // ----- ability modifiers -----
    explanations.push(ComputationExplanation {
        id: "race.elf.trait_bundle.ability_modifiers".to_owned(),
        value: 0,
        detail: format!(
            "Elf racial trait bundle — ability modifiers: PF1 Core Elf grants a fixed \
             {ELF_DEX_ADJUSTMENT:+} Dexterity, {ELF_INT_ADJUSTMENT:+} Intelligence, and \
             {ELF_CON_ADJUSTMENT:+} Constitution racial adjustment (verified against the real \
             PCGen corpus: core_essentials/races/elf/elf_abilities_race.lst's \"Elf Racial \
             Default\" ability-score row, not an alternate/optional variant — \
             BONUS:STAT|DEX,INT|2|TYPE=Racial, BONUS:STAT|CON|-2|TYPE=Racial; \
             cr_races.lst's own Elf.MOD record is only a source-page citation, not the real \
             base-race data). This is a bounded recognition record naming the fixed adjustment \
             on the deterministic pilot seam; the chosen Dexterity, Intelligence, and \
             Constitution scores are understood to already reflect it, so this record performs \
             no arithmetic and carries no fabricated mechanical value (+0)."
        ),
    });

    // ----- size -----
    explanations.push(ComputationExplanation {
        id: "race.elf.trait_bundle.size".to_owned(),
        value: 0,
        detail: format!(
            "Elf racial trait bundle — size: PF1 Core Elf is {ELF_SIZE_CATEGORY} size \
             (cr_races.lst race:elf SIZE:MEDIUM). This is a bounded recognition record naming \
             the Elf size category on the deterministic pilot seam; it contributes no numeric \
             effect to attack rolls, AC, skill checks, ability checks, or any other computed \
             value, so it carries no fabricated mechanical value (+0)"
        ),
    });

    // ----- speed -----
    explanations.push(ComputationExplanation {
        id: "race.elf.trait_bundle.speed".to_owned(),
        value: ELF_BASE_SPEED_FEET,
        detail: format!(
            "Elf racial trait bundle — speed: PF1 Core Elf has a base land speed of \
             {ELF_BASE_SPEED_FEET} ft (cr_races.lst race:elf GAIT:WALK|{ELF_BASE_SPEED_FEET}). \
             This is a grounded recognition value carrying the Elf base-speed identity on the \
             deterministic pilot seam; it contributes no computed speed-derived effect to any \
             chassis output, skill modifier, attack roll, or combat baseline"
        ),
    });

    // ----- senses -----
    // Low-light vision is a binary trait (doubles effective light for vision
    // purposes), not a distance magnitude like Dwarf Darkvision; the recognition
    // value stays +0.
    explanations.push(ComputationExplanation {
        id: "race.elf.trait_bundle.senses".to_owned(),
        value: 0,
        detail: "Elf racial trait bundle — senses: PF1 Core Elf grants low-light vision \
                  (cr_races.lst race:elf SENSE:Low-Light Vision). This is a bounded recognition \
                  record naming the Elf low-light vision identity on the deterministic pilot \
                  seam; it contributes no computed illumination or perception-derived effect to \
                  any chassis output, so it carries no fabricated mechanical value (+0)"
            .to_owned(),
    });

    // ----- Keen Senses -----
    // Flat +2 racial bonus on Perception checks. Mirrors the Dwarf Stonecunning
    // idiom (flat skill-bonus-magnitude recognition record, not a Perception
    // check-total engine).
    explanations.push(ComputationExplanation {
        id: "race.elf.trait_bundle.keen_senses".to_owned(),
        value: 2,
        detail: "Elf racial trait bundle — Keen Senses: PF1 Core Elf grants a flat +2 racial \
                  bonus on Perception checks \
                  (core_essentials/races/elf/elf_abilities_race.lst Keen Senses entry — \
                  BONUS:SKILL|Perception|KeenSensesBonus|TYPE=Racial, \
                  BONUS:VAR|KeenSensesBonus|2). This is a bounded recognition record naming \
                  only the flat racial-bonus magnitude on the deterministic pilot seam, not a \
                  Perception-check-total engine."
            .to_owned(),
    });

    // ----- Elven Immunities -----
    // Bundles two distinct sub-effects, both grounded honestly:
    //   - immunity to magic sleep effects: a flat, no-magnitude grant-only
    //     identity record, mirroring the Monk Purity of Body / Diamond Body
    //     disease/poison-immunity idiom exactly — no sleep-effect-resolution
    //     engine exists anywhere in this codebase to apply the immunity to;
    //   - a +2 racial saving throw bonus against enchantment spells and
    //     effects: a flat racial-bonus magnitude, mirroring the Keen Senses /
    //     Stonecunning / Greed flat-bonus idiom (applied to a save category
    //     instead of a skill), not a saving-throw-total engine.
    // The record's numeric value (2) names only the save-bonus magnitude;
    // the sleep immunity is named in the detail text as a non-fabricated
    // grant-only fact, contributing no additional numeric value.
    explanations.push(ComputationExplanation {
        id: "race.elf.trait_bundle.elven_immunities".to_owned(),
        value: 2,
        detail: "Elf racial trait bundle — Elven Immunities: PF1 Core Elf is immune to magic \
                  sleep effects and gets a flat +2 racial saving throw bonus against \
                  enchantment spells and effects \
                  (core_essentials/races/elf/elf_abilities_race.lst Elven Immunities entry — \
                  DESC:\"Elves are immune to magic sleep effects and get a +2 racial saving \
                  throw bonus against enchantment spells and effects.\", \
                  ABILITY:Special Ability|AUTOMATIC|Immunity to Sleep, \
                  BONUS:VAR|SaveBonus_vs_Enchantments|2|TYPE=Racial). The sleep immunity is a \
                  bounded grant-only identity record (non-fabricated): no sleep-effect- \
                  resolution engine exists anywhere in this codebase to apply the immunity to. \
                  The recognized numeric value (2) names only the flat enchantment \
                  saving-throw-bonus magnitude, not a saving-throw-total engine."
            .to_owned(),
    });

    // ----- Elven Magic -----
    // Bundles two distinct sub-effects, both grounded honestly, mirroring the
    // Elven Immunities idiom exactly:
    //   - a +2 racial bonus on caster level checks made to overcome spell
    //     resistance: a flat, no-magnitude grant-only identity record (no
    //     caster-level-check / spell-resistance-resolution engine exists
    //     anywhere in this codebase to apply the bonus to);
    //   - a +2 racial bonus on Spellcraft skill checks made to identify the
    //     properties of magic items: a flat racial-bonus magnitude,
    //     mirroring the Keen Senses / Stonecunning / Greed flat-bonus idiom
    //     (applied to the Spellcraft skill), not a Spellcraft-check-total
    //     engine.
    // This trait was not previously named in the Elf row's unproven-family
    // list (which named only weapon familiarity and bonus language grants);
    // it is a genuine, distinct PF1 Core Elf racial trait present in the
    // corpus that this slice newly recognizes.
    explanations.push(ComputationExplanation {
        id: "race.elf.trait_bundle.elven_magic".to_owned(),
        value: 2,
        detail: "Elf racial trait bundle — Elven Magic: PF1 Core Elf gets a flat +2 racial \
                  bonus on caster level checks made to overcome spell resistance, and a flat \
                  +2 racial bonus on Spellcraft skill checks made to identify the properties \
                  of magic items \
                  (core_essentials/races/elf/elf_abilities_race.lst Elven Magic entry — \
                  DESC:\"Elves receive a +2 racial bonus on caster level checks made to \
                  overcome spell resistance. In addition, elves receive a +2 racial bonus on \
                  Spellcraft skill checks made to identify the properties of magic items.\", \
                  BONUS:SITUATION|Spellcraft=to identify magic item properties|2|TYPE=Racial). \
                  The caster-level-check-vs-spell-resistance bonus is a bounded grant-only \
                  identity record (non-fabricated): no caster-level-check or \
                  spell-resistance-resolution engine exists anywhere in this codebase to apply \
                  the bonus to. The recognized numeric value (2) names only the flat \
                  Spellcraft-identify racial-bonus magnitude, not a Spellcraft-check-total \
                  engine."
            .to_owned(),
    });

    // Bounded honesty: only the seven named dimensions are grounded. This
    // replaces the generic race.semantics.unverified diagnostic for Elf
    // specifically and stays non-claim-blocking so the deterministic pilot
    // still reports computed evidence.
    diagnostics.push(ComputationDiagnostic {
        id: "race.elf.bounded_semantics".to_owned(),
        message: "Elf race semantics are grounded for the deterministic pilot's ability \
                  modifiers, size, speed, senses, Keen Senses (Perception bonus), Elven \
                  Immunities (sleep immunity plus enchantment save bonus), and Elven Magic \
                  (caster level check vs. spell resistance bonus plus Spellcraft identify \
                  bonus) trait bundle; the remaining PF1 Core Elf racial trait surface remains \
                  unverified: weapon familiarity (longbow, composite longbow, longsword, \
                  rapier, shortbow, composite shortbow), and bonus language grants. PF1 core \
                  Elves gain no racial bonus feat (unlike Human), so that family is explicitly \
                  not applicable rather than silently omitted."
            .to_owned(),
        claim_blocking: false,
    });
}

const GNOME_RACE_ID: &str = "race:gnome";
const GNOME_SIZE_CATEGORY: &str = "Small";
const GNOME_BASE_SPEED_FEET: i16 = 20;
const GNOME_CON_ADJUSTMENT: i16 = 2;
const GNOME_STR_ADJUSTMENT: i16 = -2;
/// v0.6 alpha swarm (QA-found systemic parity gap, same shape as Elf's
/// missing +2 Intelligence): verified against the real PCGen corpus,
/// `core_essentials/races/gnome/gnome_abilities_race.lst:18`'s "Gnome
/// Racial Default" ability-score row (not an alternate) --
/// `BONUS:STAT|CON,CHA|2|TYPE=Racial`, `BONUS:STAT|STR|-2|TYPE=Racial`: +2
/// Constitution, +2 Charisma, -2 Strength. This engine only grounded
/// CON/STR; Charisma was missing entirely, not even flagged as an
/// alternate.
const GNOME_CHA_ADJUSTMENT: i16 = 2;

/// SD13-E2/SD18 Gnome racial trait bundle explanation seam (mirroring the
/// Dwarf/Elf pattern for the third non-Human core race).
///
/// Surfaces six grounded PF1 Core Rulebook Gnome racial trait dimensions
/// (ability modifiers, size, speed, senses, Keen Senses, Illusion
/// Resistance) as explicit `ComputationExplanation` records so the Gnome
/// identity is legible on the runtime path rather than left behind the
/// generic `race.semantics.unverified` diagnostic every other non-Human race
/// still receives.
///
/// This function:
///   - runs only when `race_id == race:gnome`; every other race is unaffected
///     (Human, Dwarf, and Elf keep their own seams; every other non-Human race
///     keeps the generic `race.semantics.unverified` diagnostic),
///   - adds no new computed mechanical contribution beyond the flat Keen
///     Senses and Illusion Resistance bonus magnitudes: the ability-modifiers
///     record is recognition-only (the chosen Constitution/Strength scores are
///     understood to already reflect the fixed +2/-2 racial adjustment; no
///     arithmetic is performed on this seam), and the size/senses records carry
///     the grounded source value as identity only,
///   - replaces the generic `race.semantics.unverified` diagnostic with a
///     Gnome-specific `race.gnome.bounded_semantics` note naming the
///     still-unproven families explicitly (Defensive Training, Hatred, Gnome
///     Magic, weapon familiarity, and the explicit absence of any Gnome
///     racial bonus feat),
///   - is bounded to race recognition only; it deliberately grounds no Gnome
///     class-chassis interaction, no other race, and no PF1 alternate ruleset.
fn explain_gnome_race_seam(
    input: &CharacterInput,
    explanations: &mut Vec<ComputationExplanation>,
    diagnostics: &mut Vec<ComputationDiagnostic>,
) {
    if input.chosen.race_id != GNOME_RACE_ID {
        return;
    }

    // ----- ability modifiers -----
    explanations.push(ComputationExplanation {
        id: "race.gnome.trait_bundle.ability_modifiers".to_owned(),
        value: 0,
        detail: format!(
            "Gnome racial trait bundle — ability modifiers: PF1 Core Gnome grants a fixed \
             {GNOME_CON_ADJUSTMENT:+} Constitution, {GNOME_CHA_ADJUSTMENT:+} Charisma, and \
             {GNOME_STR_ADJUSTMENT:+} Strength racial adjustment (verified against the real \
             PCGen corpus: core_essentials/races/gnome/gnome_abilities_race.lst's \"Gnome \
             Racial Default\" ability-score row — BONUS:STAT|CON,CHA|2|TYPE=Racial, \
             BONUS:STAT|STR|-2|TYPE=Racial). This is a bounded recognition record naming the \
             fixed adjustment on the deterministic pilot seam; the chosen Constitution, \
             Charisma, and Strength scores are understood to already reflect it, so this record \
             performs no arithmetic and carries no fabricated mechanical value (+0)"
        ),
    });

    // ----- size -----
    explanations.push(ComputationExplanation {
        id: "race.gnome.trait_bundle.size".to_owned(),
        value: 0,
        detail: format!(
            "Gnome racial trait bundle — size: PF1 Core Gnome is {GNOME_SIZE_CATEGORY} size \
             (cr_races.lst race:gnome SIZE:SMALL). This is a bounded recognition record naming \
             the Gnome size category on the deterministic pilot seam; it grounds no numeric \
             effect (real PF1 Small size grants +1 AC, +1 attack rolls, -1 CMB/CMD, and +4 \
             Stealth, but no size-modifier term exists anywhere in this engine's combat \
             baseline for any race yet, so none of that is applied here either), so it carries \
             no fabricated mechanical value (+0)"
        ),
    });

    // ----- speed -----
    explanations.push(ComputationExplanation {
        id: "race.gnome.trait_bundle.speed".to_owned(),
        value: GNOME_BASE_SPEED_FEET,
        detail: format!(
            "Gnome racial trait bundle — speed: PF1 Core Gnome has a base land speed of \
             {GNOME_BASE_SPEED_FEET} ft (cr_races.lst race:gnome GAIT:WALK|{GNOME_BASE_SPEED_FEET}). \
             This is a grounded recognition value carrying the Gnome base-speed identity on the \
             deterministic pilot seam; it contributes no computed speed-derived effect to any \
             chassis output, skill modifier, attack roll, or combat baseline"
        ),
    });

    // ----- senses -----
    explanations.push(ComputationExplanation {
        id: "race.gnome.trait_bundle.senses".to_owned(),
        value: 0,
        detail: "Gnome racial trait bundle — senses: PF1 Core Gnome grants low-light vision \
                  (cr_races.lst race:gnome SENSE:Low-Light Vision). This is a bounded \
                  recognition record naming the Gnome low-light vision identity on the \
                  deterministic pilot seam; it contributes no computed illumination or \
                  perception-derived effect to any chassis output, so it carries no fabricated \
                  mechanical value (+0)"
            .to_owned(),
    });

    // ----- Keen Senses -----
    explanations.push(ComputationExplanation {
        id: "race.gnome.trait_bundle.keen_senses".to_owned(),
        value: 2,
        detail: "Gnome racial trait bundle — Keen Senses: PF1 Core Gnome grants a flat +2 \
                  racial bonus on Perception skill checks \
                  (core_essentials/races/gnome/gnome_abilities_race.lst Keen Senses entry — \
                  BONUS:SKILL|Perception|KeenSensesBonus|TYPE=Racial, \
                  BONUS:VAR|KeenSensesBonus|2). This is a bounded recognition record naming \
                  only the flat racial-bonus magnitude on the deterministic pilot seam, not a \
                  Perception-check-total engine."
            .to_owned(),
    });

    // ----- Illusion Resistance -----
    explanations.push(ComputationExplanation {
        id: "race.gnome.trait_bundle.illusion_resistance".to_owned(),
        value: 2,
        detail: "Gnome racial trait bundle — Illusion Resistance: PF1 Core Gnome grants a \
                  flat +2 racial saving throw bonus against illusion spells and effects \
                  (core_essentials/races/gnome/gnome_abilities_race.lst Illusion Resistance \
                  entry — BONUS:VAR|SaveBonus_vs_Illusions|2|TYPE=Racial). This is a bounded \
                  recognition record naming only the flat racial-bonus magnitude on the \
                  deterministic pilot seam, not a saving-throw-total engine."
            .to_owned(),
    });

    // ----- Defensive Training -----
    explanations.push(ComputationExplanation {
        id: "race.gnome.trait_bundle.defensive_training".to_owned(),
        value: 4,
        detail: "Gnome racial trait bundle — Defensive Training: PF1 Core Gnome grants a flat \
                  +4 dodge bonus to AC against monsters of the giant subtype \
                  (core_essentials/races/gnome/gnome_abilities_race.lst Defensive Training \
                  entry — BONUS:VAR|RacialDefensiveTrainingBonus|4). This is a bounded \
                  recognition record naming only the flat racial-bonus magnitude on the \
                  deterministic pilot seam, not an AC-total engine and not a \
                  giant-subtype-detection engine (no \"is the target a giant\" resolution is \
                  fabricated)."
            .to_owned(),
    });

    // ----- Hatred -----
    explanations.push(ComputationExplanation {
        id: "race.gnome.trait_bundle.hatred".to_owned(),
        value: 1,
        detail: "Gnome racial trait bundle — Hatred: PF1 Core Gnome grants a flat +1 racial \
                  bonus on attack rolls against humanoid creatures of the reptilian and \
                  goblinoid subtypes \
                  (core_essentials/races/gnome/gnome_abilities_race.lst Hatred entry — \
                  BONUS:VAR|Gnome_Hatred_AttackBonus|1). This is a bounded recognition record \
                  naming only the flat racial-bonus magnitude on the deterministic pilot seam, \
                  not an attack-roll-total engine and not a reptilian/goblinoid-subtype- \
                  detection engine (no \"is the target a reptilian humanoid or goblinoid\" \
                  resolution is fabricated)."
            .to_owned(),
    });

    // Bounded honesty: only the eight named dimensions are grounded. This replaces
    // the generic race.semantics.unverified diagnostic for Gnome specifically and
    // stays non-claim-blocking so the deterministic pilot still reports computed
    // evidence.
    diagnostics.push(ComputationDiagnostic {
        id: "race.gnome.bounded_semantics".to_owned(),
        message: "Gnome race semantics are grounded for the deterministic pilot's ability \
                  modifiers, size, speed, senses, Keen Senses (Perception bonus), Illusion \
                  Resistance (illusion-save bonus), Defensive Training (dodge bonus to AC \
                  against giants), and Hatred (attack-roll bonus against reptilian humanoids \
                  and goblinoids) trait bundle; the remaining PF1 Core Gnome racial trait \
                  surface remains unverified: Gnome Magic (spell-like abilities keyed to a high \
                  Charisma), and weapon familiarity (gnome hooked hammer). PF1 core Gnomes gain \
                  no racial bonus feat (unlike Human), so that family is explicitly not \
                  applicable rather than silently omitted."
            .to_owned(),
        claim_blocking: false,
    });
}

const HALF_ELF_RACE_ID: &str = "race:half-elf";
const HALF_ELF_SIZE_CATEGORY: &str = "Medium";
const HALF_ELF_BASE_SPEED_FEET: i16 = 30;
const HALF_ELF_ABILITY_BONUS_CHOICE_ID: &str = "choice:half_elf_ability_bonus";

/// SD13-E2/SD18 Half-Elf racial trait bundle explanation seam (mirroring the
/// Dwarf/Elf/Gnome recognition pattern for the fourth non-Human core race, but
/// with a choice-based ability bonus like Human's rather than a fixed pair).
///
/// Surfaces six grounded PF1 Core Rulebook Half-Elf racial trait dimensions
/// (chosen ability-bonus target, size, speed, senses, Keen Senses, Elven
/// Immunities) as explicit `ComputationExplanation` records so the Half-Elf
/// identity is legible on the runtime path rather than left behind the
/// generic `race.semantics.unverified` diagnostic every other non-Human race
/// still receives.
///
/// This function:
///   - runs only when `race_id == race:half-elf`; every other race is unaffected
///     (Human, Dwarf, Elf, and Gnome keep their own seams; every other non-Human
///     race keeps the generic `race.semantics.unverified` diagnostic),
///   - adds no new computed mechanical contribution beyond the flat Keen
///     Senses and Elven Immunities enchantment-save bonus magnitudes: the
///     ability-bonus-target record surfaces the already-computed modifier for
///     the chosen ability as recognition (mirroring
///     `race.human.ability_bonus_target`'s shape), the size/senses records
///     carry the grounded source value as identity only, and Elven
///     Immunities' sleep immunity is a bounded grant-only identity record
///     (no sleep-effect-resolution engine exists in this codebase),
///   - replaces the generic `race.semantics.unverified` diagnostic with a
///     Half-Elf-specific `race.half_elf.bounded_semantics` note naming the
///     still-unproven families explicitly (Adaptability, Multitalented),
///   - is bounded to race recognition only; it deliberately grounds no Half-Elf
///     class-chassis interaction, no other race, and no PF1 alternate ruleset.
fn explain_half_elf_race_seam(
    input: &CharacterInput,
    ability_modifiers: &AbilityModifiers,
    explanations: &mut Vec<ComputationExplanation>,
    diagnostics: &mut Vec<ComputationDiagnostic>,
) {
    if input.chosen.race_id != HALF_ELF_RACE_ID {
        return;
    }

    // ----- ability bonus (choice-based, like Human) -----
    if let Some(selection) = choice_selection(input, HALF_ELF_ABILITY_BONUS_CHOICE_ID) {
        let ability = selection
            .strip_prefix(ABILITY_SELECTION_PREFIX)
            .unwrap_or(selection);
        let modifier = ability_modifier_for(ability_modifiers, ability);
        explanations.push(ComputationExplanation {
            id: "race.half_elf.trait_bundle.ability_bonus_target".to_owned(),
            value: modifier,
            detail: format!(
                "Half-Elf racial trait bundle — ability bonus: PF1 Core Half-Elf grants a \
                 player-chosen +2 to any one ability score ({HALF_ELF_ABILITY_BONUS_CHOICE_ID} \
                 -> {selection}); the chosen {ability} score yields modifier {modifier:+}. This \
                 is a bounded recognition record naming the chosen target on the deterministic \
                 pilot seam; the chosen score is understood to already reflect the +2 \
                 adjustment, so this record performs no arithmetic beyond surfacing the \
                 already-computed modifier"
            ),
        });
    }

    // ----- size -----
    explanations.push(ComputationExplanation {
        id: "race.half_elf.trait_bundle.size".to_owned(),
        value: 0,
        detail: format!(
            "Half-Elf racial trait bundle — size: PF1 Core Half-Elf is \
             {HALF_ELF_SIZE_CATEGORY} size (cr_races.lst race:half-elf SIZE:MEDIUM). This is a \
             bounded recognition record naming the Half-Elf size category on the deterministic \
             pilot seam; it contributes no numeric effect to attack rolls, AC, skill checks, \
             ability checks, or any other computed value, so it carries no fabricated \
             mechanical value (+0)"
        ),
    });

    // ----- speed -----
    explanations.push(ComputationExplanation {
        id: "race.half_elf.trait_bundle.speed".to_owned(),
        value: HALF_ELF_BASE_SPEED_FEET,
        detail: format!(
            "Half-Elf racial trait bundle — speed: PF1 Core Half-Elf has a base land speed of \
             {HALF_ELF_BASE_SPEED_FEET} ft \
             (cr_races.lst race:half-elf GAIT:WALK|{HALF_ELF_BASE_SPEED_FEET}). This is a \
             grounded recognition value carrying the Half-Elf base-speed identity on the \
             deterministic pilot seam; it contributes no computed speed-derived effect to any \
             chassis output, skill modifier, attack roll, or combat baseline"
        ),
    });

    // ----- senses -----
    explanations.push(ComputationExplanation {
        id: "race.half_elf.trait_bundle.senses".to_owned(),
        value: 0,
        detail: "Half-Elf racial trait bundle — senses: PF1 Core Half-Elf grants low-light \
                  vision (cr_races.lst race:half-elf SENSE:Low-Light Vision). This is a bounded \
                  recognition record naming the Half-Elf low-light vision identity on the \
                  deterministic pilot seam; it contributes no computed illumination or \
                  perception-derived effect to any chassis output, so it carries no fabricated \
                  mechanical value (+0)"
            .to_owned(),
    });

    // ----- Keen Senses -----
    explanations.push(ComputationExplanation {
        id: "race.half_elf.trait_bundle.keen_senses".to_owned(),
        value: 2,
        detail: "Half-Elf racial trait bundle — Keen Senses: PF1 Core Half-Elf grants a flat \
                  +2 racial bonus on Perception skill checks \
                  (core_essentials/races/half_elf/halfelf_abilities_race.lst Keen Senses entry \
                  — BONUS:SKILL|Perception|KeenSensesBonus|TYPE=Racial, \
                  BONUS:VAR|KeenSensesBonus|2). This is a bounded recognition record naming \
                  only the flat racial-bonus magnitude on the deterministic pilot seam, not a \
                  Perception-check-total engine."
            .to_owned(),
    });

    // ----- Elven Immunities -----
    // Bundles two distinct sub-effects, both grounded honestly, mirroring the
    // already-landed Elf Elven Immunities idiom exactly:
    //   - immunity to magic sleep effects: a flat, no-magnitude grant-only
    //     identity record, mirroring the Monk Purity of Body / Diamond Body
    //     disease/poison-immunity idiom — no sleep-effect-resolution engine
    //     exists anywhere in this codebase to apply the immunity to;
    //   - a +2 racial saving throw bonus against enchantment spells and
    //     effects: a flat racial-bonus magnitude, mirroring the Keen Senses
    //     flat-bonus idiom (applied to a save category instead of a skill),
    //     not a saving-throw-total engine.
    // The record's numeric value (2) names only the save-bonus magnitude;
    // the sleep immunity is named in the detail text as a non-fabricated
    // grant-only fact, contributing no additional numeric value.
    explanations.push(ComputationExplanation {
        id: "race.half_elf.trait_bundle.elven_immunities".to_owned(),
        value: 2,
        detail: "Half-Elf racial trait bundle — Elven Immunities: PF1 Core Half-Elf is immune \
                  to magic sleep effects and gets a flat +2 racial saving throw bonus against \
                  enchantment spells and effects \
                  (core_essentials/races/half_elf/halfelf_abilities_race.lst Elven Immunities \
                  entry — DESC:\"Half-elves are immune to magic sleep effects and get a +2 \
                  racial saving throw bonus against enchantment spells and effects.\", \
                  ABILITY:Special Ability|AUTOMATIC|Immunity to Sleep, \
                  BONUS:VAR|SaveBonus_vs_Enchantments|2|TYPE=Racial). The sleep immunity is a \
                  bounded grant-only identity record (non-fabricated): no sleep-effect- \
                  resolution engine exists anywhere in this codebase to apply the immunity to. \
                  The recognized numeric value (2) names only the flat enchantment \
                  saving-throw-bonus magnitude, not a saving-throw-total engine."
            .to_owned(),
    });

    // Bounded honesty: only the six named dimensions are grounded. This replaces
    // the generic race.semantics.unverified diagnostic for Half-Elf specifically
    // and stays non-claim-blocking so the deterministic pilot still reports
    // computed evidence.
    diagnostics.push(ComputationDiagnostic {
        id: "race.half_elf.bounded_semantics".to_owned(),
        message: "Half-Elf race semantics are grounded for the deterministic pilot's chosen \
                  ability-bonus target, size, speed, senses, Keen Senses (Perception bonus), \
                  and Elven Immunities (sleep immunity plus enchantment save bonus) trait \
                  bundle; the remaining PF1 Core Half-Elf racial trait surface remains \
                  unverified: Adaptability (a bonus Skill Focus feat in a chosen skill at 1st \
                  level), and Multitalented (counting both parent classes as favored classes)."
            .to_owned(),
        claim_blocking: false,
    });
}

const HALF_ORC_RACE_ID: &str = "race:half-orc";
const HALF_ORC_SIZE_CATEGORY: &str = "Medium";
const HALF_ORC_BASE_SPEED_FEET: i16 = 30;
const HALF_ORC_DARKVISION_FEET: i16 = 60;
const HALF_ORC_ABILITY_BONUS_CHOICE_ID: &str = "choice:half_orc_ability_bonus";
const HALF_ORC_INTIMIDATING_BONUS: i16 = 2;

/// SD13-E2/SD18 Half-Orc racial trait bundle explanation seam (mirroring the
/// Half-Elf choice-based ability-bonus pattern for the fifth non-Human core
/// race, with Darkvision instead of low-light vision).
///
/// Surfaces five grounded PF1 Core Rulebook Half-Orc racial trait dimensions
/// (chosen ability-bonus target, size, speed, senses, Intimidating) as
/// explicit `ComputationExplanation` records so the Half-Orc identity is
/// legible on the runtime path rather than left behind the generic
/// `race.semantics.unverified` diagnostic every other non-Human race still
/// receives.
///
/// This function:
///   - runs only when `race_id == race:half-orc`; every other race is
///     unaffected (Human, Dwarf, Elf, Gnome, and Half-Elf keep their own seams;
///     every other non-Human race keeps the generic `race.semantics.unverified`
///     diagnostic),
///   - adds no new computed mechanical contribution beyond the flat
///     Intimidating skill-bonus magnitude (SD18): the ability-bonus-target
///     record surfaces the already-computed modifier for the chosen ability as
///     recognition, the size/senses records carry the grounded source value as
///     identity only, and Intimidating names only the flat racial-bonus
///     magnitude (mirroring the Dwarf Stonecunning / Elf/Gnome/Half-Elf Keen
///     Senses idiom) — no Intimidate-check-total engine is introduced,
///   - replaces the generic `race.semantics.unverified` diagnostic with a
///     Half-Orc-specific `race.half_orc.bounded_semantics` note naming the
///     still-unproven families explicitly (Orc Ferocity, weapon familiarity),
///   - is bounded to race recognition only; it deliberately grounds no Half-Orc
///     class-chassis interaction, no other race, and no PF1 alternate ruleset.
fn explain_half_orc_race_seam(
    input: &CharacterInput,
    ability_modifiers: &AbilityModifiers,
    explanations: &mut Vec<ComputationExplanation>,
    diagnostics: &mut Vec<ComputationDiagnostic>,
) {
    if input.chosen.race_id != HALF_ORC_RACE_ID {
        return;
    }

    // ----- ability bonus (choice-based, like Half-Elf) -----
    if let Some(selection) = choice_selection(input, HALF_ORC_ABILITY_BONUS_CHOICE_ID) {
        let ability = selection
            .strip_prefix(ABILITY_SELECTION_PREFIX)
            .unwrap_or(selection);
        let modifier = ability_modifier_for(ability_modifiers, ability);
        explanations.push(ComputationExplanation {
            id: "race.half_orc.trait_bundle.ability_bonus_target".to_owned(),
            value: modifier,
            detail: format!(
                "Half-Orc racial trait bundle — ability bonus: PF1 Core Half-Orc grants a \
                 player-chosen +2 to any one ability score \
                 ({HALF_ORC_ABILITY_BONUS_CHOICE_ID} -> {selection}); the chosen {ability} score \
                 yields modifier {modifier:+}. This is a bounded recognition record naming the \
                 chosen target on the deterministic pilot seam; the chosen score is understood \
                 to already reflect the +2 adjustment, so this record performs no arithmetic \
                 beyond surfacing the already-computed modifier"
            ),
        });
    }

    // ----- size -----
    explanations.push(ComputationExplanation {
        id: "race.half_orc.trait_bundle.size".to_owned(),
        value: 0,
        detail: format!(
            "Half-Orc racial trait bundle — size: PF1 Core Half-Orc is \
             {HALF_ORC_SIZE_CATEGORY} size (cr_races.lst race:half-orc SIZE:MEDIUM). This is a \
             bounded recognition record naming the Half-Orc size category on the deterministic \
             pilot seam; it contributes no numeric effect to attack rolls, AC, skill checks, \
             ability checks, or any other computed value, so it carries no fabricated \
             mechanical value (+0)"
        ),
    });

    // ----- speed -----
    explanations.push(ComputationExplanation {
        id: "race.half_orc.trait_bundle.speed".to_owned(),
        value: HALF_ORC_BASE_SPEED_FEET,
        detail: format!(
            "Half-Orc racial trait bundle — speed: PF1 Core Half-Orc has a base land speed of \
             {HALF_ORC_BASE_SPEED_FEET} ft \
             (cr_races.lst race:half-orc GAIT:WALK|{HALF_ORC_BASE_SPEED_FEET}). This is a \
             grounded recognition value carrying the Half-Orc base-speed identity on the \
             deterministic pilot seam; it contributes no computed speed-derived effect to any \
             chassis output, skill modifier, attack roll, or combat baseline"
        ),
    });

    // ----- senses -----
    explanations.push(ComputationExplanation {
        id: "race.half_orc.trait_bundle.senses".to_owned(),
        value: HALF_ORC_DARKVISION_FEET,
        detail: format!(
            "Half-Orc racial trait bundle — senses: PF1 Core Half-Orc grants Darkvision \
             {HALF_ORC_DARKVISION_FEET} ft (cr_races.lst race:half-orc SENSE:Darkvision \
             ({HALF_ORC_DARKVISION_FEET} ft)). This is a grounded recognition value carrying \
             the Half-Orc Darkvision identity on the deterministic pilot seam; it contributes \
             no computed low-light or perception-derived effect to any chassis output"
        ),
    });

    // ----- intimidating (flat skill-bonus idiom, mirroring Dwarf Stonecunning /
    // Elf/Gnome/Half-Elf Keen Senses) -----
    explanations.push(ComputationExplanation {
        id: "race.half_orc.trait_bundle.intimidating".to_owned(),
        value: HALF_ORC_INTIMIDATING_BONUS,
        detail: format!(
            "Half-Orc racial trait bundle — Intimidating: PF1 Core Half-Orc grants a flat \
             {HALF_ORC_INTIMIDATING_BONUS:+} racial bonus on Intimidate skill checks \
             (halforc_abilities_race.lst — Intimidating entry, \
             BONUS:SKILL|Intimidate|{HALF_ORC_INTIMIDATING_BONUS}|TYPE=Racial). This is a \
             bounded recognition record naming only the flat racial-bonus magnitude, mirroring \
             the Dwarf Stonecunning / Elf Keen Senses / Gnome Keen Senses / Half-Elf Keen \
             Senses skill-bonus idiom already established on this seam; it is deliberately NOT \
             an Intimidate-check-total engine"
        ),
    });

    // Bounded honesty: five dimensions are now grounded. This replaces the
    // generic race.semantics.unverified diagnostic for Half-Orc specifically
    // and stays non-claim-blocking so the deterministic pilot still reports
    // computed evidence.
    diagnostics.push(ComputationDiagnostic {
        id: "race.half_orc.bounded_semantics".to_owned(),
        message: "Half-Orc race semantics are grounded for the deterministic pilot's chosen \
                  ability-bonus target, size, speed, senses, and Intimidating trait bundle; the \
                  remaining PF1 Core Half-Orc racial trait surface remains unverified: Orc \
                  Ferocity (fighting on for one more round after being brought below 0 hit \
                  points), and weapon familiarity (orc double axe, falchion, and treating any \
                  weapon with 'orc' in its name as martial)."
            .to_owned(),
        claim_blocking: false,
    });
}

const HALFLING_RACE_ID: &str = "race:halfling";
const HALFLING_SIZE_CATEGORY: &str = "Small";
const HALFLING_BASE_SPEED_FEET: i16 = 20;
const HALFLING_DEX_ADJUSTMENT: i16 = 2;
const HALFLING_STR_ADJUSTMENT: i16 = -2;
/// v0.6 alpha swarm (QA-found systemic parity gap, same shape as Elf's
/// missing +2 Intelligence): verified against the real PCGen corpus,
/// `core_essentials/races/halfling/halfling_abilities_race.lst:18`'s
/// "Halfling Racial Default" ability-score row (not an alternate) --
/// `BONUS:STAT|DEX,CHA|2|TYPE=Racial`, `BONUS:STAT|STR|-2|TYPE=Racial`: +2
/// Dexterity, +2 Charisma, -2 Strength. This engine only grounded DEX/STR;
/// Charisma was missing entirely, not even flagged as an alternate.
const HALFLING_CHA_ADJUSTMENT: i16 = 2;
const HALFLING_FEARLESS_SAVE_VS_FEAR_BONUS: i16 = 2;
const HALFLING_LUCK_ALL_SAVES_BONUS: i16 = 1;

/// SD13-E2 Halfling racial trait bundle explanation seam (mirroring the
/// Dwarf/Elf/Gnome fixed-ability-pair pattern for the sixth and final
/// non-Human core race).
///
/// Surfaces six grounded PF1 Core Rulebook Halfling racial trait dimensions
/// (ability modifiers, size, speed, senses, Keen Senses, Sure-Footed) as
/// explicit `ComputationExplanation` records so the Halfling identity is
/// legible on the runtime path rather than left behind the generic
/// `race.semantics.unverified` diagnostic.
///
/// This function:
///   - runs only when `race_id == race:halfling`; every other race is
///     unaffected (Human, Dwarf, Elf, Gnome, Half-Elf, and Half-Orc keep their
///     own seams),
///   - adds no new computed mechanical contribution beyond the flat Keen
///     Senses / Sure-Footed skill-bonus magnitudes: the ability-modifiers
///     record is recognition-only (the chosen Dexterity/Strength scores are
///     understood to already reflect the fixed +2/-2 racial adjustment; no
///     arithmetic is performed on this seam), the size/senses records carry
///     the grounded source value as identity only, Keen Senses names only the
///     flat +2 Perception racial-bonus magnitude, and Sure-Footed names only
///     the flat +2 Acrobatics/Climb racial-bonus magnitude (both mirroring
///     the Dwarf Stonecunning / Elf/Gnome/Half-Elf Keen Senses / Half-Orc
///     Intimidating idiom, not a skill-check-total engine),
///   - replaces the generic `race.semantics.unverified` diagnostic with a
///     Halfling-specific `race.halfling.bounded_semantics` note naming the
///     still-unproven families explicitly (Fearless, Halfling Luck, weapon
///     familiarity, and the explicit absence of any Halfling racial bonus
///     feat),
///   - is bounded to race recognition only; it deliberately grounds no
///     Halfling class-chassis interaction, no other race, and no PF1
///     alternate ruleset.
fn explain_halfling_race_seam(
    input: &CharacterInput,
    explanations: &mut Vec<ComputationExplanation>,
    diagnostics: &mut Vec<ComputationDiagnostic>,
) {
    if input.chosen.race_id != HALFLING_RACE_ID {
        return;
    }

    // ----- ability modifiers -----
    explanations.push(ComputationExplanation {
        id: "race.halfling.trait_bundle.ability_modifiers".to_owned(),
        value: 0,
        detail: format!(
            "Halfling racial trait bundle — ability modifiers: PF1 Core Halfling grants a \
             fixed {HALFLING_DEX_ADJUSTMENT:+} Dexterity, {HALFLING_CHA_ADJUSTMENT:+} Charisma, \
             and {HALFLING_STR_ADJUSTMENT:+} Strength racial adjustment (verified against the \
             real PCGen corpus: \
             core_essentials/races/halfling/halfling_abilities_race.lst's \"Halfling Racial \
             Default\" ability-score row — BONUS:STAT|DEX,CHA|2|TYPE=Racial, \
             BONUS:STAT|STR|-2|TYPE=Racial). This is a bounded recognition record naming the \
             fixed adjustment on the deterministic pilot seam; the chosen Dexterity, Charisma, \
             and Strength scores are understood to already reflect it, so this record performs \
             no arithmetic and carries no fabricated mechanical value (+0)"
        ),
    });

    // ----- size -----
    explanations.push(ComputationExplanation {
        id: "race.halfling.trait_bundle.size".to_owned(),
        value: 0,
        detail: format!(
            "Halfling racial trait bundle — size: PF1 Core Halfling is \
             {HALFLING_SIZE_CATEGORY} size (cr_races.lst race:halfling SIZE:SMALL). This is a \
             bounded recognition record naming the Halfling size category on the deterministic \
             pilot seam; it grounds no numeric effect (real PF1 Small size grants +1 AC, +1 \
             attack rolls, -1 CMB/CMD, and +4 Stealth, but no size-modifier term exists anywhere \
             in this engine's combat baseline for any race yet, so none of that is applied here \
             either), so it carries no fabricated mechanical value (+0)"
        ),
    });

    // ----- speed -----
    explanations.push(ComputationExplanation {
        id: "race.halfling.trait_bundle.speed".to_owned(),
        value: HALFLING_BASE_SPEED_FEET,
        detail: format!(
            "Halfling racial trait bundle — speed: PF1 Core Halfling has a base land speed of \
             {HALFLING_BASE_SPEED_FEET} ft \
             (cr_races.lst race:halfling GAIT:WALK|{HALFLING_BASE_SPEED_FEET}). This is a \
             grounded recognition value carrying the Halfling base-speed identity on the \
             deterministic pilot seam; it contributes no computed speed-derived effect to any \
             chassis output, skill modifier, attack roll, or combat baseline"
        ),
    });

    // ----- senses -----
    // Bounded "no special senses" classification, mirroring Human's pattern:
    // PF1 Core Halflings have ordinary vision (no darkvision, no low-light vision).
    explanations.push(ComputationExplanation {
        id: "race.halfling.trait_bundle.senses".to_owned(),
        value: 0,
        detail: "Halfling racial trait bundle — senses: PF1 Core Halfling grants no special \
                  senses (cr_races.lst race:halfling carries no SENSE tag; darkvision, \
                  low-light vision, and other sense bonuses are absent). This is a bounded \
                  no-effect classification record on the deterministic pilot seam; it carries \
                  no fabricated sense bonus and contributes no computed value (+0)"
            .to_owned(),
    });

    // ----- Keen Senses (flat skill-bonus idiom, mirroring Dwarf Stonecunning /
    // Elf/Gnome/Half-Elf Keen Senses / Half-Orc Intimidating) -----
    explanations.push(ComputationExplanation {
        id: "race.halfling.trait_bundle.keen_senses".to_owned(),
        value: 2,
        detail: "Halfling racial trait bundle — Keen Senses: PF1 Core Halfling grants a flat \
                  +2 racial bonus on Perception skill checks \
                  (core_essentials/races/halfling/halfling_abilities_race.lst Keen Senses entry \
                  — BONUS:SKILL|Perception|KeenSensesBonus|TYPE=Racial, \
                  BONUS:VAR|KeenSensesBonus|2). This is a bounded recognition record naming \
                  only the flat racial-bonus magnitude on the deterministic pilot seam, \
                  mirroring the Dwarf Stonecunning / Elf Keen Senses / Gnome Keen Senses / \
                  Half-Elf Keen Senses / Half-Orc Intimidating skill-bonus idiom already \
                  established on this seam; it is deliberately NOT a Perception-check-total \
                  engine."
            .to_owned(),
    });

    // ----- Sure-Footed (flat skill-bonus idiom, mirroring Keen Senses above and
    // the Dwarf Stonecunning / Elf/Gnome/Half-Elf Keen Senses / Half-Orc
    // Intimidating skill-bonus idiom already established on this seam) -----
    explanations.push(ComputationExplanation {
        id: "race.halfling.trait_bundle.sure_footed".to_owned(),
        value: 2,
        detail: "Halfling racial trait bundle — Sure-Footed: PF1 Core Halfling grants a flat \
                  +2 racial bonus on Acrobatics and Climb skill checks \
                  (core_essentials/races/halfling/halfling_abilities_race.lst Sure-Footed \
                  entry — BONUS:SKILL|Acrobatics,Climb|2|TYPE=Racial). This is a bounded \
                  recognition record naming only the flat racial-bonus magnitude on the \
                  deterministic pilot seam, mirroring the Keen Senses / Dwarf Stonecunning / \
                  Elf Keen Senses / Gnome Keen Senses / Half-Elf Keen Senses / Half-Orc \
                  Intimidating skill-bonus idiom already established on this seam; it is \
                  deliberately NOT an Acrobatics/Climb-check-total engine."
            .to_owned(),
    });

    // ----- Fearless (flat racial saving-throw-bonus idiom, mirroring Dwarf
    // Hardy's flat +2 saving-throw-vs-poison/spells bonuses applied to a
    // Halfling-specific named save category) -----
    // Grounded flat +2 racial bonus on saving throws against fear
    // (core_essentials/races/halfling/halfling_abilities_race.lst Fearless
    // entry — BONUS:VAR|SaveBonus_vs_Fear|2|TYPE=Racial). This is deliberately
    // NOT a saving-throw-total engine: the recognized value names only the
    // flat racial-bonus magnitude on the deterministic pilot seam, mirroring
    // the already-grounded Dwarf Hardy flat racial saving-throw-bonus idiom
    // on this same seam shape. Halfling Luck (a separate +1 luck bonus on
    // ALL saving throws, which explicitly stacks with Fearless per the
    // corpus DESC text) remains a distinct, still-unproven family.
    explanations.push(ComputationExplanation {
        id: "race.halfling.trait_bundle.fearless".to_owned(),
        value: HALFLING_FEARLESS_SAVE_VS_FEAR_BONUS,
        detail: format!(
            "Halfling racial trait bundle — Fearless: PF1 Core Halfling grants a flat \
             {HALFLING_FEARLESS_SAVE_VS_FEAR_BONUS:+} racial bonus on saving throws against \
             fear (halfling_abilities_race.lst Fearless entry — \
             BONUS:VAR|SaveBonus_vs_Fear|{HALFLING_FEARLESS_SAVE_VS_FEAR_BONUS}|TYPE=Racial). \
             This is a bounded flat saving-throw-bonus-magnitude recognition record naming the \
             Fearless identity on the deterministic pilot seam, mirroring the already-grounded \
             Dwarf Hardy flat racial saving-throw-bonus idiom; no saving-throw-total or \
             fear-effect-resolution engine exists anywhere in this codebase, so no check \
             resolution is fabricated from this record"
        ),
    });

    // ----- Halfling Luck (flat racial saving-throw-bonus idiom, mirroring
    // Fearless above and the Dwarf Hardy flat racial saving-throw-bonus idiom
    // already established on this seam, applied to a broader "all saving
    // throws" scope rather than a single named save category) -----
    // Grounded flat +1 racial bonus on all saving throws
    // (core_essentials/races/halfling/halfling_abilities_race.lst Halfling
    // Luck entry — BONUS:VAR|Halfling_HalflingLuck_SaveBonus|1|TYPE=Racial).
    // This is deliberately NOT a saving-throw-total engine: the recognized
    // value names only the flat racial-bonus magnitude on the deterministic
    // pilot seam, mirroring the already-grounded Dwarf Hardy / Halfling
    // Fearless flat racial saving-throw-bonus idiom on this same seam shape.
    // Per the corpus DESC text, this bonus explicitly stacks with Fearless
    // (a distinct, already-grounded fear-specific save bonus).
    explanations.push(ComputationExplanation {
        id: "race.halfling.trait_bundle.halfling_luck".to_owned(),
        value: HALFLING_LUCK_ALL_SAVES_BONUS,
        detail: format!(
            "Halfling racial trait bundle — Halfling Luck: PF1 Core Halfling grants a flat \
             {HALFLING_LUCK_ALL_SAVES_BONUS:+} racial bonus on all saving throws \
             (halfling_abilities_race.lst Halfling Luck entry — \
             BONUS:VAR|Halfling_HalflingLuck_SaveBonus|{HALFLING_LUCK_ALL_SAVES_BONUS}|TYPE=Racial). \
             This is a bounded flat saving-throw-bonus-magnitude recognition record naming the \
             Halfling Luck identity on the deterministic pilot seam, mirroring the \
             already-grounded Dwarf Hardy / Halfling Fearless flat racial saving-throw-bonus \
             idiom; no saving-throw-total or luck-effect-resolution engine exists anywhere in \
             this codebase, so no check resolution is fabricated from this record"
        ),
    });

    // Bounded honesty: only the eight named dimensions are grounded. This replaces
    // the generic race.semantics.unverified diagnostic for Halfling specifically
    // and stays non-claim-blocking so the deterministic pilot still reports
    // computed evidence.
    diagnostics.push(ComputationDiagnostic {
        id: "race.halfling.bounded_semantics".to_owned(),
        message: "Halfling race semantics are grounded for the deterministic pilot's ability \
                  modifiers, size, speed, senses, Keen Senses (Perception bonus), \
                  Sure-Footed (Acrobatics/Climb bonus), Fearless (saving-throw-vs-fear \
                  bonus), and Halfling Luck (all-saving-throws bonus) trait bundle; the \
                  remaining PF1 Core Halfling racial trait surface remains unverified: weapon \
                  familiarity (sling and thrown weapons). PF1 core Halflings gain no racial \
                  bonus feat (unlike Human), so that family is explicitly not applicable \
                  rather than silently omitted."
            .to_owned(),
        claim_blocking: false,
    });
}

/// SD13-E6-F3a Human racial trait bundle explanation seam.
///
/// Surfaces each remaining PF1 Standard Human racial trait dimension (size,
/// speed, senses, extra skill ranks) as an explicit `ComputationExplanation`
/// record so the trait bundle is legible on the runtime path rather than left
/// as an incidental side-effect or a folklore claim. Three of the four
/// dimensions carry the grounded PF1 source value as a recognition record;
/// the senses dimension carries a bounded "no special senses" classification
/// because PF1 Standard Human grants no special sense bonus.
///
/// This function:
///   - runs only when `race_id == race:human`; non-Human races stay on the
///     bounded diagnostics the `explain_race_seam` dispatcher emits (the
///     Half-Elf bounded diagnostic or the `race.semantics.unverified`
///     catch-all),
///   - adds no new computed mechanical contribution; each record carries the
///     grounded source value as recognition and contributes nothing to the
///     chassis totals, selected-skill modifiers, combat baseline, or AC,
///   - replaces the previous "Human size, speed, senses, extra skill ranks
///     remain unverified" non-claim-blocking note from
///     `race.human.bounded_semantics` with explicit per-dimension records,
///   - is bounded to the deterministic Human Fighter level-1/2/3 pilot
///     posture implicitly via the caller; it deliberately grounds no other
///     Human racial variant (alternate Human racial traits, variant Humans,
///     half-Humans), no other race, and no PF1 alternate ruleset.
fn explain_human_trait_bundle(
    input: &CharacterInput,
    explanations: &mut Vec<ComputationExplanation>,
    _diagnostics: &mut Vec<ComputationDiagnostic>,
) {
    if input.chosen.race_id != HUMAN_RACE_ID {
        return;
    }

    // ----- size -----
    // Recognition record only; carries the grounded Human size category name
    // as the recognition value so the explanation reads as the humanoid
    // identity rather than fabricating a numeric contribution.
    explanations.push(ComputationExplanation {
        id: "race.human.trait_bundle.size".to_owned(),
        value: 0,
        detail: format!(
            "Human racial trait bundle — size: PF1 Standard Human is {HUMAN_SIZE_CATEGORY} size \
             (cr_races.lst race:human SIZE:MEDIUM). This is a bounded recognition record naming \
             the Human size category on the deterministic pilot seam; it contributes no numeric \
             effect to attack rolls, AC, skill checks, ability checks, or any other computed \
             value, so it carries no fabricated mechanical value (+0)"
        ),
    });

    // ----- speed -----
    // Recognition record for the 30 ft base land speed. The bounded
    // selected-skill and combat baselines never consult base speed, so this
    // record is identity-only — no computed speed-derived value is fabricated.
    explanations.push(ComputationExplanation {
        id: "race.human.trait_bundle.speed".to_owned(),
        value: HUMAN_BASE_SPEED_FEET,
        detail: format!(
            "Human racial trait bundle — speed: PF1 Standard Human has a base land speed of \
             {HUMAN_BASE_SPEED_FEET} ft (cr_races.lst race:human GAIT:WALK|{HUMAN_BASE_SPEED_FEET}). \
             This is a grounded recognition value carrying the human base-speed identity on the \
             deterministic pilot seam; it contributes no computed speed-derived effect to any \
             chassis output, skill modifier, attack roll, or combat baseline"
        ),
    });

    // ----- senses -----
    // Bounded "no special senses" classification. PF1 Standard Human grants
    // no special senses (darkvision, low-light, scent, etc.), so this
    // dimension is classified explicitly as no-effect rather than a silent
    // omission or a fabricated sense bonus.
    explanations.push(ComputationExplanation {
        id: "race.human.trait_bundle.senses".to_owned(),
        value: 0,
        detail: "Human racial trait bundle — senses: PF1 Standard Human grants no special senses \
             (cr_races.lst race:human carries no SENSE tag for Standard Human; darkvision, \
             low-light vision, scent, and other sense bonuses are absent). This is a bounded \
             no-effect classification record on the deterministic pilot seam; it carries no \
             fabricated sense bonus and contributes no computed value (+0)"
            .to_owned(),
    });

    // ----- extra skill ranks -----
    // Recognition record for the extra-skill-ranks Human trait. PF1 Standard
    // Human grants 4 extra skill points at 1st level and 1 extra skill rank
    // per additional level thereafter; this slice surfaces both numbers as a
    // recognition record and explicitly does not propagate them through the
    // bounded selected-skill modifier computation (which controls the
    // deterministic Climb / Intimidate / Swim rank-1 posture only).
    explanations.push(ComputationExplanation {
        id: "race.human.trait_bundle.extra_skill_ranks".to_owned(),
        value: i16::from(HUMAN_EXTRA_SKILL_RANKS_PER_LEVEL),
        detail: format!(
            "Human racial trait bundle — extra skill ranks: PF1 Standard Human gains \
             {HUMAN_EXTRA_SKILL_POINTS_AT_LEVEL_1} extra skill points at 1st level and \
             {HUMAN_EXTRA_SKILL_RANKS_PER_LEVEL} extra skill rank per additional level thereafter \
             (cr_races.lst race:human BONUS:SKILL|...). The recognition value \
             ({HUMAN_EXTRA_SKILL_RANKS_PER_LEVEL:+}) carries the per-additional-level extra-rank \
             identity on the deterministic pilot seam; this slice does not propagate these \
             extra skill points/rank through the bounded Climb/Intimidate/Swim rank-1 selected \
             skill-modifier computation, so the bounded fighter-posture skill totals remain \
             grounded by the canonical rank-1 posture rather than by the unbounded Human extra \
             skill-rank rule"
        ),
    });
}

/// Return the selection id chosen for the named choice set, if present.
pub(crate) fn choice_selection<'a>(input: &'a CharacterInput, choice_set_id: &str) -> Option<&'a str> {
    input
        .chosen
        .selected_choices
        .iter()
        .find(|c| c.choice_set_id == choice_set_id)
        .map(|c| c.selection_id.as_str())
}

/// Return a human-readable display name (e.g. "Knowledge (arcana)") when the given
/// selection names a specific Knowledge skill (a "knowledge:<skill>"-shaped token).
/// Returns `None` for any selection that is not itself shaped that way. This recognizes
/// the whole Knowledge skill family rather than a restricted enum list, because the PF1
/// Core Rulebook Arcane bloodline's own class-skill grant text reads "Knowledge (any
/// one)" — any Knowledge skill is legal, not just Knowledge (arcana).
fn knowledge_skill_display_name(selection: &str) -> Option<String> {
    selection
        .strip_prefix("knowledge:")
        .filter(|skill| !skill.is_empty())
        .map(|skill| format!("Knowledge ({skill})"))
}

/// Look up the already-computed modifier for a named ability. Unknown ability names
/// contribute nothing rather than fabricating a value.
fn ability_modifier_for(modifiers: &AbilityModifiers, ability: &str) -> i16 {
    match ability {
        "strength" => modifiers.strength,
        "dexterity" => modifiers.dexterity,
        "constitution" => modifiers.constitution,
        "intelligence" => modifiers.intelligence,
        "wisdom" => modifiers.wisdom,
        "charisma" => modifiers.charisma,
        _ => 0,
    }
}

/// The bounded Fighter milestone level this surface grounds, if any. Returns the
/// single Fighter level when the chosen input is exactly a single-class Fighter at
/// one of the supported milestone levels (1, 2, or 3). Returns `None` for no
/// Fighter, a non-Fighter class, a multiclass mix, or a level-4+ Fighter this slice
/// does not yet ground — each of which stays claim-blocked as before.
pub(crate) fn supported_fighter_level(input: &CharacterInput) -> Option<u8> {
    match input.chosen.class_levels.as_slice() {
        [class_level]
            if class_level.class_id == FIGHTER_CLASS_ID
                && (1..=MAX_SUPPORTED_FIGHTER_LEVEL).contains(&class_level.level) =>
        {
            Some(class_level.level)
        }
        _ => None,
    }
}

/// Fighter armor-training profile for a given Fighter level. Armor training 1 is
/// gained at level 3, armor training 2 at level 7, armor training 3 at level
/// 11, and armor training 4 at level 15 (SD18 widening); before level 3 there
/// is no armor-training effect.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct FighterArmorTraining {
    /// Armor-training rank (0 before level 3, 1 from level 3, 2 from level 7,
    /// 3 from level 11, 4 from level 15).
    pub(crate) rank: u8,
    /// Reduction applied to the worn armor's armor-check penalty (moves it toward 0).
    pub(crate) armor_check_reduction: i16,
    /// Increase applied to the worn armor's maximum Dexterity bonus.
    pub(crate) max_dex_increase: i16,
}

pub(crate) fn fighter_armor_training(level: u8) -> FighterArmorTraining {
    if level >= FIGHTER_ARMOR_TRAINING_4_LEVEL {
        FighterArmorTraining {
            rank: 4,
            armor_check_reduction: ARMOR_TRAINING_4_ARMOR_CHECK_REDUCTION,
            max_dex_increase: ARMOR_TRAINING_4_MAX_DEX_INCREASE,
        }
    } else if level >= FIGHTER_ARMOR_TRAINING_3_LEVEL {
        FighterArmorTraining {
            rank: 3,
            armor_check_reduction: ARMOR_TRAINING_3_ARMOR_CHECK_REDUCTION,
            max_dex_increase: ARMOR_TRAINING_3_MAX_DEX_INCREASE,
        }
    } else if level >= FIGHTER_ARMOR_TRAINING_2_LEVEL {
        FighterArmorTraining {
            rank: 2,
            armor_check_reduction: ARMOR_TRAINING_2_ARMOR_CHECK_REDUCTION,
            max_dex_increase: ARMOR_TRAINING_2_MAX_DEX_INCREASE,
        }
    } else if level >= FIGHTER_ARMOR_TRAINING_1_LEVEL {
        FighterArmorTraining {
            rank: 1,
            armor_check_reduction: ARMOR_TRAINING_1_ARMOR_CHECK_REDUCTION,
            max_dex_increase: ARMOR_TRAINING_1_MAX_DEX_INCREASE,
        }
    } else {
        FighterArmorTraining {
            rank: 0,
            armor_check_reduction: 0,
            max_dex_increase: 0,
        }
    }
}

/// The effective Chain Shirt armor-check penalty at a Fighter level, after any
/// armor-training reduction. Capped at 0 so the reduction never turns the penalty
/// into a bonus.
fn effective_chain_shirt_armor_check_penalty(level: u8) -> i16 {
    (CHAIN_SHIRT_ARMOR_CHECK_PENALTY + fighter_armor_training(level).armor_check_reduction).min(0)
}

/// The Fighter weapon-training rank at the given level: 0 before level 5, then
/// 1 + (level - 5) / 4 (Weapon Training 1 at level 5, Weapon Training 2 at
/// level 9 within this bounded levels-1-10 surface).
fn fighter_weapon_training_rank(level: u8) -> i16 {
    if level < FIGHTER_WEAPON_TRAINING_1_LEVEL {
        return 0;
    }
    i16::from(1 + (level - FIGHTER_WEAPON_TRAINING_1_LEVEL) / FIGHTER_WEAPON_TRAINING_RANK_LEVEL_STRIDE)
}

/// The weapon-training attack-roll bonus for the first chosen weapon group at
/// the given Fighter level, gated on the canonical
/// `choice:fighter_weapon_training_group -> group:heavy_blades` selection (the
/// group the deterministic Longsword falls under). The bonus equals the
/// weapon-training rank: +1 at levels 5-8, +2 at levels 9-10. Returns 0 before
/// level 5 or when the group choice is absent — the canonical-choice validator
/// (`CANONICAL_FIGHTER_FEAT_CHOICES`) separately claim-blocks a
/// present-but-non-canonical selection, so this function only needs to
/// distinguish "canonical" from "absent or anything else."
pub(crate) fn fighter_weapon_training_attack_bonus(input: &CharacterInput, level: u8) -> i16 {
    if choice_selection(input, FIGHTER_WEAPON_TRAINING_GROUP_CHOICE_ID)
        == Some(HEAVY_BLADES_GROUP_SELECTION)
    {
        fighter_weapon_training_rank(level)
    } else {
        0
    }
}

/// The Fighter Bravery Will-save-vs-fear bonus magnitude at the given level: 0
/// before level 2, then 1 + (level - 2) / 4 (+1 at level 2, +2 at level 6, +3 at
/// level 10 within this bounded levels-1-10 surface). A flat magnitude only —
/// no fear-condition or save-resolution engine exists on this compute surface.
fn fighter_bravery_bonus(level: u8) -> i16 {
    if level < FIGHTER_BRAVERY_LEVEL {
        return 0;
    }
    i16::from(1 + (level - FIGHTER_BRAVERY_LEVEL) / FIGHTER_BRAVERY_RANK_LEVEL_STRIDE)
}

/// Compute the bounded Fighter base chassis for the supported milestone levels
/// (1, 2, or 3), or block the claim if the input is not a supported single-class
/// Fighter posture for this narrow slice.
fn compute_fighter_chassis(
    input: &CharacterInput,
    explanations: &mut Vec<ComputationExplanation>,
    diagnostics: &mut Vec<ComputationDiagnostic>,
) -> (i16, BaseSaves) {
    let Some(level) = supported_fighter_level(input) else {
        diagnostics.push(ComputationDiagnostic {
            id: "class_chassis.unsupported".to_owned(),
            message: format!(
                "base class chassis is only supported for a single-class {FIGHTER_CLASS_ID} at \
                 levels 1-{MAX_SUPPORTED_FIGHTER_LEVEL}; chosen class levels {:?} do not provide it, \
                 so no chassis values were computed",
                input.chosen.class_levels
            ),
            claim_blocking: true,
        });
        return (0, BaseSaves::default());
    };

    // Grounded Fighter base progression from cr_classes.lst:139, evaluated at the
    // chosen level:
    //   BONUS:COMBAT|BASEAB|classlevel                -> level (full base attack)
    //   BONUS:SAVE|BASE.Fortitude|classlevel/2+2      -> level/2 + 2 (good save)
    //   BONUS:SAVE|BASE.Reflex,BASE.Will|classlevel/3 -> level/3 (poor saves)
    let level_value = i16::from(level);
    let base_attack_bonus = level_value;
    let base_saves = BaseSaves {
        fortitude: level_value / 2 + 2,
        reflex: level_value / 3,
        will: level_value / 3,
    };

    explanations.push(ComputationExplanation {
        id: "class_chassis.base_attack_bonus".to_owned(),
        value: base_attack_bonus,
        detail: format!(
            "Fighter level {level} base attack bonus from cr_classes.lst:139 \
             BONUS:COMBAT|BASEAB|classlevel = {base_attack_bonus}"
        ),
    });
    explanations.push(ComputationExplanation {
        id: "class_chassis.base_save.fortitude".to_owned(),
        value: base_saves.fortitude,
        detail: format!(
            "Fighter level {level} base Fortitude save from cr_classes.lst:139 \
             BONUS:SAVE|BASE.Fortitude|classlevel/2+2 = {}",
            base_saves.fortitude
        ),
    });
    explanations.push(ComputationExplanation {
        id: "class_chassis.base_save.reflex".to_owned(),
        value: base_saves.reflex,
        detail: format!(
            "Fighter level {level} base Reflex save from cr_classes.lst:139 \
             BONUS:SAVE|BASE.Reflex,BASE.Will|classlevel/3 = {}",
            base_saves.reflex
        ),
    });
    explanations.push(ComputationExplanation {
        id: "class_chassis.base_save.will".to_owned(),
        value: base_saves.will,
        detail: format!(
            "Fighter level {level} base Will save from cr_classes.lst:139 \
             BONUS:SAVE|BASE.Reflex,BASE.Will|classlevel/3 = {}",
            base_saves.will
        ),
    });

    (base_attack_bonus, base_saves)
}

/// SD-21 Epic 6 (E6.25) / Epic 7 (E7.28); widened v0.6 alpha swarm task 4:
/// dispatch the base-attack-bonus / base-save chassis pillar to the supported
/// single class, to `compute_multiclass_base_chassis` for a supported
/// length-2+ multiclass mix, or return `None` when the input is a single
/// class this dispatch does not yet recognize, or a multiclass mix
/// containing an unrecognized class. Each recognized class's own
/// `compute_<class>_chassis` function (or the shared table-driven
/// `compute_generic_table_chassis` path) still independently checks its own
/// level range and pushes `class_chassis.unsupported` itself when out of
/// range, so this dispatch only needs to route by `class_id` / mix shape.
pub(crate) fn has_supported_class_chassis(input: &CharacterInput) -> bool {
    supported_fighter_level(input).is_some()
        || supported_wizard_level(input).is_some()
        || is_supported_multiclass_mix(input)
        || is_supported_generic_single_class(input)
        || is_supported_skald_single_class(input)
        || is_supported_bloodrager_single_class(input)
        || is_supported_brawler_single_class(input)
        || is_supported_hunter_single_class(input)
        || is_supported_cavalier_single_class(input)
        || is_supported_alchemist_single_class(input)
        || is_supported_inquisitor_single_class(input)
        || is_supported_oracle_single_class(input)
        || is_supported_arcanist_single_class(input)
        || is_supported_warpriest_single_class(input)
        || is_supported_slayer_single_class(input)
        || is_supported_swashbuckler_single_class(input)
        || is_supported_investigator_single_class(input)
        || is_supported_witch_single_class(input)
        || is_supported_shaman_single_class(input)
}

/// v0.6 alpha swarm, risks item 8 (Cavalier Mount closure): whether
/// `input` is a single-class Cavalier at a level within
/// `apg::class_chassis_resolve`'s declared ceiling for Cavalier -- the
/// FIRST widening of this gate to any APG class, mirroring the four ACG
/// exact-match gates exactly (`== Some(ApgClassId::Cavalier)`, not a
/// broad `.is_some()` that would admit any of the 6 APG classes).
fn is_supported_cavalier_single_class(input: &CharacterInput) -> bool {
    let [class_level] = input.chosen.class_levels.as_slice() else {
        return false;
    };
    if ApgClassId::from_class_id_str(&class_level.class_id) != Some(ApgClassId::Cavalier) {
        return false;
    }
    apg::class_chassis_resolve(ApgClassId::Cavalier, class_level.level, RuleSetId::Apg).is_some()
}

