/// v0.6 alpha swarm, task #19 (feat-effects Category B): the four
/// "Extra <resource>" General feats each add a flat amount to a per-day
/// resource total that this engine ALREADY computes, rather than
/// introducing a new mechanism.
///
/// Every magnitude was verified twice before these tests were written --
/// against this repo's own `feat_data/general.rs` catalog and against the
/// raw PCGen `cr_feats.lst` record -- and they agree:
/// `BONUS:VAR|RageDuration|6`, `BONUS:VAR|BardicPerformanceDuration|6`,
/// `BONUS:VAR|KiPoints|2`, `BONUS:VAR|LayOnHandsTimes|2`.
///
/// Each test differences the SAME character with and without the feat, so
/// no assertion can pass on a coincidental absolute value, and each
/// checks that sibling resources are untouched.
#[cfg(test)]
mod extra_resource_feat_tests {
    use super::{ActiveState, build_pilot_headless_receipt, CharacterClassLevel, CharacterInput};
    use crate::rules_core::character_input::{
        load_character_input_fixture, ClassAbilityActivation,
    };

    const FIGHTER_LEVEL_1_FIXTURE: &str = include_str!(
        "../../tests/fixtures/rules_core/pf1_human_fighter_level1_ge06_deterministic_input.txt"
    );

    fn character(class_id: &str, level: u8) -> CharacterInput {
        let result = load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE);
        assert!(result.diagnostics.is_empty(), "fixture must load cleanly");
        let mut input = result.character_input.expect("valid fixture");
        input.chosen.class_levels =
            vec![CharacterClassLevel { class_id: class_id.to_owned(), level }];
        input
    }

    fn explanation_value(input: &CharacterInput, id: &str) -> Option<i16> {
        build_pilot_headless_receipt(input)
            .computation
            .explanations
            .iter()
            .find(|e| e.id == id)
            .map(|e| e.value)
    }

    /// Drives one Extra-<resource> feat end to end: the same character
    /// with and without the feat, asserting the named total rises by
    /// exactly the corpus magnitude.
    fn assert_feat_adds(class_id: &str, level: u8, feat: &str, total_id: &str, expected: i16) {
        let without = character(class_id, level);
        let base = explanation_value(&without, total_id)
            .unwrap_or_else(|| panic!("{total_id} must be computed for a bare {class_id}"));

        let mut with = without.clone();
        with.chosen.selected_feats.push(feat.to_owned());
        let raised = explanation_value(&with, total_id)
            .unwrap_or_else(|| panic!("{total_id} must still be computed with {feat}"));

        assert_eq!(
            raised - base,
            expected,
            "{feat} must raise {total_id} by exactly {expected} (base {base}, with feat {raised})"
        );
    }

    #[test]
    fn extra_rage_adds_six_rounds_to_the_real_rage_total() {
        assert_feat_adds(
            "class:barbarian",
            1,
            "Extra Rage",
            "class_chassis.barbarian.rage_rounds_per_day",
            6,
        );
    }

    #[test]
    fn extra_performance_adds_six_rounds_to_the_real_bardic_performance_total() {
        assert_feat_adds(
            "class:bard",
            1,
            "Extra Performance",
            "class_chassis.bard.bardic_performance_rounds_per_day",
            6,
        );
    }

    #[test]
    fn extra_ki_adds_two_points_to_the_real_ki_pool_total() {
        // Monk's Ki Pool is a 4th-level class feature.
        assert_feat_adds("class:monk", 4, "Extra Ki", "class_chassis.monk.ki_pool_size", 2);
    }

    #[test]
    fn extra_lay_on_hands_adds_two_uses_to_the_real_lay_on_hands_total() {
        // Paladin's Lay On Hands is a 2nd-level class feature.
        assert_feat_adds(
            "class:paladin",
            2,
            "Extra Lay On Hands",
            "class_chassis.paladin.lay_on_hands_uses_per_day",
            2,
        );
    }

    /// None of the four may leak onto a resource it does not name. Each
    /// feat is applied to a character who owns a DIFFERENT resource, and
    /// that resource must not move.
    #[test]
    fn each_extra_feat_leaves_every_sibling_resource_untouched() {
        let cases = [
            ("class:barbarian", 1u8, "class_chassis.barbarian.rage_rounds_per_day"),
            ("class:bard", 1, "class_chassis.bard.bardic_performance_rounds_per_day"),
            ("class:monk", 4, "class_chassis.monk.ki_pool_size"),
            ("class:paladin", 2, "class_chassis.paladin.lay_on_hands_uses_per_day"),
        ];
        let feats = ["Extra Rage", "Extra Performance", "Extra Ki", "Extra Lay On Hands"];

        for (index, (class_id, level, total_id)) in cases.iter().enumerate() {
            let baseline = character(class_id, *level);
            let base = explanation_value(&baseline, total_id)
                .unwrap_or_else(|| panic!("{total_id} must be computed"));

            for (feat_index, feat) in feats.iter().enumerate() {
                if feat_index == index {
                    continue;
                }
                let mut other = baseline.clone();
                other.chosen.selected_feats.push((*feat).to_owned());
                assert_eq!(
                    explanation_value(&other, total_id),
                    Some(base),
                    "{feat} must not move {total_id}"
                );
            }
        }
    }

    /// All four feats are `STACK:YES MULT:YES` in the corpus -- genuinely
    /// repeatable, with each instance stacking. Taking Extra Rage twice
    /// grants 12 rounds, not 6, so the bonus must COUNT occurrences in
    /// `selected_feats` rather than merely test for presence.
    ///
    /// Missed on the first pass (2026-07-27) because the corpus record
    /// was read through a `grep -E "^(BONUS|PRE)"` filter that discarded
    /// the `STACK:`/`MULT:` lines entirely -- a filter chosen around the
    /// fields expected to matter, which hid one that did.
    #[test]
    fn repeated_extra_feats_stack_because_all_four_are_stack_yes_mult_yes() {
        let cases = [
            ("class:barbarian", 1u8, "Extra Rage", "class_chassis.barbarian.rage_rounds_per_day", 6),
            (
                "class:bard",
                1,
                "Extra Performance",
                "class_chassis.bard.bardic_performance_rounds_per_day",
                6,
            ),
            ("class:monk", 4, "Extra Ki", "class_chassis.monk.ki_pool_size", 2),
            (
                "class:paladin",
                2,
                "Extra Lay On Hands",
                "class_chassis.paladin.lay_on_hands_uses_per_day",
                2,
            ),
        ];

        for (class_id, level, feat, total_id, per_instance) in cases {
            let base = character(class_id, level);
            let baseline = explanation_value(&base, total_id).expect("total must compute");

            for instances in 1..=3i16 {
                let mut input = base.clone();
                for _ in 0..instances {
                    input.chosen.selected_feats.push(feat.to_owned());
                }
                let raised = explanation_value(&input, total_id).expect("total must compute");
                assert_eq!(
                    raised - baseline,
                    per_instance * instances,
                    "{feat} taken {instances}x must grant {per_instance} each ({class_id})"
                );
            }
        }
    }

    /// Each feat carries `PREABILITY:1,CATEGORY=Special Ability,TYPE.<X>`
    /// -- it requires the underlying class feature. A character without
    /// that class must never have the feat grounded against some other
    /// class's total, and must not gain the resource record at all.
    #[test]
    fn extra_feats_never_ground_for_a_character_lacking_the_underlying_class_feature() {
        let totals = [
            "class_chassis.barbarian.rage_rounds_per_day",
            "class_chassis.bard.bardic_performance_rounds_per_day",
            "class_chassis.monk.ki_pool_size",
            "class_chassis.paladin.lay_on_hands_uses_per_day",
        ];
        let mut fighter = character("class:fighter", 1);
        for feat in ["Extra Rage", "Extra Performance", "Extra Ki", "Extra Lay On Hands"] {
            fighter.chosen.selected_feats.push(feat.to_owned());
        }

        let receipt = build_pilot_headless_receipt(&fighter);
        for total_id in totals {
            assert!(
                !receipt.computation.explanations.iter().any(|e| e.id == total_id),
                "a Fighter holding every Extra feat must not gain {total_id}: {:?}",
                receipt.computation.explanations.iter().map(|e| &e.id).collect::<Vec<_>>()
            );
        }
    }

    /// A Monk below the Ki Pool's own 4th-level gate, and a Paladin below
    /// Lay On Hands' 2nd-level gate, must not gain the resource from the
    /// feat alone -- the feat widens an existing pool, it does not create
    /// one the character has not yet earned.
    #[test]
    fn extra_feats_do_not_grant_a_resource_before_its_own_class_level_gate() {
        let mut monk = character("class:monk", 1);
        monk.chosen.selected_feats.push("Extra Ki".to_owned());
        let ki = explanation_value(&monk, "class_chassis.monk.ki_pool_size");
        assert!(
            ki.is_none() || ki == Some(0),
            "a level-1 Monk has no ki pool for Extra Ki to widen, got {ki:?}"
        );

        let mut paladin = character("class:paladin", 1);
        paladin.chosen.selected_feats.push("Extra Lay On Hands".to_owned());
        let loh = explanation_value(&paladin, "class_chassis.paladin.lay_on_hands_uses_per_day");
        assert!(
            loh.is_none() || loh == Some(0),
            "a level-1 Paladin has no lay on hands for the feat to widen, got {loh:?}"
        );
    }

    /// The load-bearing consistency check. Rage's and Bardic
    /// Performance's per-day budgets are read in THREE separate places
    /// each (the displayed total plus two activation-budget checks), so
    /// raising only the displayed total would let a character be shown 13
    /// rounds while still being judged over budget at 8 -- the same
    /// two-spot divergence the Rage/Charmed Life budget work already hit
    /// once.
    ///
    /// A Barbarian with Extra Rage who has consumed more than the BASE
    /// budget but no more than the EXTENDED one must still be validly
    /// raging, which is only true if the budget check sees the feat too.
    #[test]
    fn extra_rage_widens_the_activation_budget_not_merely_the_displayed_total() {
        let mut input = character("class:barbarian", 1);
        input.chosen.selected_feats.push("Extra Rage".to_owned());
        // Fixture Constitution 14 (+2): base budget is 4 + 2 = 6 rounds,
        // extended to 12 by Extra Rage. 9 is over base, within extended.
        input.chosen.class_ability_activations.push(ClassAbilityActivation {
            ability_id: "rage".to_owned(),
            active_state: ActiveState::EquippedActive,
            rounds_consumed_today: Some(9),
        });

        let receipt = build_pilot_headless_receipt(&input);
        let over_budget = receipt
            .computation
            .diagnostics
            .iter()
            .any(|d| d.id.contains("rounds_exceeded") || d.id.contains("budget"));

        assert!(
            !over_budget,
            "9 rounds is within the Extra-Rage-extended budget; the activation check must see \
             the feat, not just the displayed total: {:?}",
            receipt.computation.diagnostics
        );
    }

    /// Same three-spot property for Bardic Performance, whose displayed
    /// total is computed INLINE while its two budget checks call the
    /// shared formula -- the likeliest place for the two to drift apart.
    #[test]
    fn extra_performance_widens_the_activation_budget_not_merely_the_displayed_total() {
        let mut input = character("class:bard", 1);
        input.chosen.selected_feats.push("Extra Performance".to_owned());
        // Fixture Charisma 8 (-1): base budget is 4 + (-1) = 3 rounds,
        // extended to 9. 5 is over base, within extended.
        input.chosen.class_ability_activations.push(ClassAbilityActivation {
            ability_id: "bardic_performance".to_owned(),
            active_state: ActiveState::EquippedActive,
            rounds_consumed_today: Some(5),
        });

        let receipt = build_pilot_headless_receipt(&input);
        assert!(
            !receipt
                .computation
                .diagnostics
                .iter()
                .any(|d| d.id.contains("rounds_exceeded")),
            "5 rounds is within the Extra-Performance-extended budget; the activation check must \
             see the feat: {:?}",
            receipt.computation.diagnostics
        );
    }
}

/// v0.6 alpha swarm, task #20 (2026-07-27): class-granted feats must
/// reach the `feat_effects` producers.
///
/// Three feats are granted automatically by class level and never appear
/// in `selected_feats`, because a player never picks them: Monk's
/// Improved Unarmed Strike and Stunning Fist at 1st level, and Ranger's
/// Endurance at 3rd. Every producer keys on `selected_feats`, so those
/// characters were invisible to every feat-presence check.
#[cfg(test)]
mod class_granted_feat_tests {
    use super::{class_granted_feats, CharacterClassLevel, CharacterInput};
    use crate::rules_core::character_input::load_character_input_fixture;

    const FIGHTER_LEVEL_1_FIXTURE: &str = include_str!(
        "../../tests/fixtures/rules_core/pf1_human_fighter_level1_ge06_deterministic_input.txt"
    );

    fn character(class_id: &str, level: u8) -> CharacterInput {
        let result = load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE);
        let mut input = result.character_input.expect("valid fixture");
        input.chosen.class_levels =
            vec![CharacterClassLevel { class_id: class_id.to_owned(), level }];
        input
    }

    /// Monk gains BOTH Improved Unarmed Strike and Stunning Fist at 1st
    /// level ("even if he does not meet the prerequisites"), verified
    /// against `cr_abilities_class.lst`'s own
    /// `ABILITY:FEAT|AUTOMATIC|Improved Unarmed Strike` and
    /// `ABILITY:FEAT|VIRTUAL|Stunning Fist`.
    #[test]
    fn a_monk_is_granted_improved_unarmed_strike_and_stunning_fist_from_first_level() {
        for level in [1u8, 4, 20] {
            let granted = class_granted_feats(&character("class:monk", level));
            assert!(
                granted.contains(&"Improved Unarmed Strike"),
                "level {level} Monk must be granted Improved Unarmed Strike: {granted:?}"
            );
            assert!(
                granted.contains(&"Stunning Fist"),
                "level {level} Monk must be granted Stunning Fist: {granted:?}"
            );
        }
    }

    /// Ranger's Endurance is gated at 3rd level
    /// (`PREVARGTEQ:Ranger_CFP_Level,3`), so a level 1-2 Ranger must NOT
    /// be credited with it.
    #[test]
    fn a_ranger_is_granted_endurance_only_from_third_level() {
        for level in [1u8, 2] {
            let granted = class_granted_feats(&character("class:ranger", level));
            assert!(
                !granted.contains(&"Endurance"),
                "level {level} Ranger has not gained Endurance yet: {granted:?}"
            );
        }
        for level in [3u8, 5, 20] {
            let granted = class_granted_feats(&character("class:ranger", level));
            assert!(
                granted.contains(&"Endurance"),
                "level {level} Ranger genuinely has Endurance: {granted:?}"
            );
        }
    }

    /// No other class grants any of these, and a Fighter grants none.
    #[test]
    fn a_class_without_automatic_feat_grants_is_credited_with_none() {
        for class_id in ["class:fighter", "class:wizard", "class:barbarian"] {
            assert!(
                class_granted_feats(&character(class_id, 20)).is_empty(),
                "{class_id} grants no automatic feats in this codebase"
            );
        }
    }

    /// A multiclass Monk/Ranger gets both classes' grants, each at its
    /// own level gate.
    #[test]
    fn a_multiclass_character_gets_each_classs_own_grants_at_its_own_gate() {
        let mut input = character("class:monk", 1);
        input.chosen.class_levels.push(CharacterClassLevel {
            class_id: "class:ranger".to_owned(),
            level: 3,
        });
        let granted = class_granted_feats(&input);
        assert!(granted.contains(&"Stunning Fist"));
        assert!(granted.contains(&"Improved Unarmed Strike"));
        assert!(granted.contains(&"Endurance"));
    }

    /// The granted feats genuinely reach the `feat_effects` producers
    /// through `effective_feats` -- the whole point of the wiring. Proven
    /// against the real union rather than the derivation alone.
    #[test]
    fn granted_feats_reach_the_producers_through_effective_feats() {
        let input = character("class:ranger", 3);
        let effective = crate::rules_core::feat_effects::effective_feats(
            &input.chosen.selected_feats,
            &class_granted_feats(&input),
        );
        assert!(
            effective.iter().any(|f| f == "Endurance"),
            "a level-3 Ranger's Endurance must be visible to every producer: {effective:?}"
        );
        assert!(
            crate::rules_core::feat_effects::endurance_check_bonus_from_feats(&effective) > 0,
            "the producer that keys on Endurance must now see it"
        );
    }

    /// A Ranger who ALSO picked Endurance from the catalog must not hold
    /// it twice -- `effective_feats` appends only when absent, and that
    /// matters because other producers count duplicates for STACK:YES
    /// feats.
    #[test]
    fn a_granted_feat_already_chosen_is_not_duplicated() {
        let mut input = character("class:ranger", 3);
        input.chosen.selected_feats.push("Endurance".to_owned());
        let effective = crate::rules_core::feat_effects::effective_feats(
            &input.chosen.selected_feats,
            &class_granted_feats(&input),
        );
        assert_eq!(
            effective.iter().filter(|f| *f == "Endurance").count(),
            1,
            "Endurance must appear exactly once: {effective:?}"
        );
    }
}

/// v0.6 alpha swarm, task #6 (Cavalier, 2026-07-27): the five named
/// features this closure grounds, plus the decoy-variable guard.
#[cfg(test)]
mod cavalier_named_feature_tests {
    use super::{
        build_pilot_headless_receipt, ActiveState, CharacterClassLevel, CharacterInput,
        CAVALIER_CHALLENGE_ABILITY_ID, CAVALIER_CLASS_ID, CAVALIER_ORDER_CHOICE_ID,
        ORDER_OF_THE_SWORD_SELECTION,
    };
    use crate::rules_core::character_input::{
        load_character_input_fixture, ClassAbilityActivation, SelectedChoice,
    };

    const FIGHTER_LEVEL_1_FIXTURE: &str = include_str!(
        "../../tests/fixtures/rules_core/pf1_human_fighter_level1_ge06_deterministic_input.txt"
    );

    fn cavalier(level: u8) -> CharacterInput {
        let result = load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE);
        let mut input = result.character_input.expect("valid fixture");
        input.chosen.class_levels =
            vec![CharacterClassLevel { class_id: CAVALIER_CLASS_ID.to_owned(), level }];
        input
    }

    fn value(input: &CharacterInput, id: &str) -> Option<i16> {
        build_pilot_headless_receipt(input)
            .computation
            .explanations
            .iter()
            .find(|e| e.id == id)
            .map(|e| e.value)
    }

    /// Challenge's uses/day is `(level+2)/3`, re-derived across the full
    /// range from the corpus token rather than spot-checked.
    #[test]
    fn challenge_uses_per_day_matches_the_corpus_formula_at_every_level() {
        for (level, expected) in
            [(1u8, 1i16), (2, 1), (3, 1), (4, 2), (6, 2), (7, 3), (10, 4), (20, 7)]
        {
            assert_eq!(
                super::cavalier_challenge_uses_per_day(level),
                expected,
                "level {level}: (level + 2)/3"
            );
        }
    }

    /// The decoy guard. Two similarly-named variables exist in the
    /// corpus: the real `OrderChallengeBonus` (`CavalierLVL/4`, consumed
    /// by all six Orders) and `CavalierOrderChallengeBonus`
    /// (`(CavalierLVL+3)/4`), which is defined on the base Challenge
    /// record -- the natural first place to look -- and referenced
    /// NOWHERE. This closure grounds neither (every order challenge rider
    /// is opponent- or ally-conditioned), so the guard is that no
    /// Cavalier explanation ever carries the decoy's value shape.
    #[test]
    fn no_grounded_value_uses_the_never_consumed_decoy_formula() {
        // At level 5 the two formulas diverge: real = 5/4 = 1,
        // decoy = (5+3)/4 = 2. The pipeline check stays at level 1 for
        // the companion-boundary reason noted above.
        let receipt = build_pilot_headless_receipt(&cavalier(1));
        let decoy = (5 + 3) / 4;
        assert_eq!(decoy, 2, "the decoy really does differ from the real formula at level 5");
        assert!(
            !receipt
                .computation
                .explanations
                .iter()
                .any(|e| e.id.contains("order_challenge")),
            "no order-challenge-bonus record is grounded at all this closure: {:?}",
            receipt.computation.explanations
        );
    }

    /// Challenge's -2 AC penalty applies only while actively
    /// challenging, and lands on the REAL armor class total -- proven by
    /// differencing the same character with and without the activation.
    #[test]
    fn an_active_challenge_lowers_the_real_armor_class_total_by_two() {
        let idle = cavalier(1);
        let without = value(&idle, "defense.baseline_armor_class").expect("AC computed");

        let mut challenging = idle.clone();
        challenging.chosen.class_ability_activations.push(ClassAbilityActivation {
            ability_id: CAVALIER_CHALLENGE_ABILITY_ID.to_owned(),
            active_state: ActiveState::EquippedActive,
            rounds_consumed_today: None,
        });
        let with = value(&challenging, "defense.baseline_armor_class").expect("AC computed");

        assert_eq!(with - without, -2, "an active challenge costs 2 AC");
        assert_eq!(
            value(&challenging, "class_feature.apg.cavalier.challenge_armor_class_penalty"),
            Some(-2)
        );
        assert_eq!(
            value(&idle, "class_feature.apg.cavalier.challenge_not_active"),
            Some(0),
            "an idle cavalier gets the honest not-active record instead"
        );
    }

    /// A non-Cavalier carrying a spoofed challenge activation must not
    /// lose armor class.
    #[test]
    fn a_spoofed_challenge_never_lowers_a_non_cavaliers_armor_class() {
        let result = load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE);
        let mut fighter = result.character_input.expect("valid fixture");
        let clean = value(&fighter, "defense.baseline_armor_class");
        fighter.chosen.class_ability_activations.push(ClassAbilityActivation {
            ability_id: CAVALIER_CHALLENGE_ABILITY_ID.to_owned(),
            active_state: ActiveState::EquippedActive,
            rounds_consumed_today: None,
        });
        assert_eq!(
            value(&fighter, "defense.baseline_armor_class"),
            clean,
            "a Fighter's AC is untouched by a spoofed Cavalier challenge"
        );
    }

    /// Expert Trainer is a 4th-level feature and must not ground before
    /// its own gate.
    ///
    /// Pipeline assertions stay at level 1: `ground_horse_companion_stat_block`
    /// carries a pre-existing `debug_assert` that only companion level 1
    /// is grounded, a documented boundary predating this closure (Hunter
    /// hit the identical one). Higher levels are exercised through the
    /// pure formula instead of expanding that unrelated limitation.
    #[test]
    fn expert_trainer_grounds_only_from_fourth_level() {
        assert_eq!(
            value(&cavalier(1), "class_feature.apg.cavalier.expert_trainer_bonus"),
            None,
            "a level-1 Cavalier has not gained Expert Trainer"
        );
        for (level, expected) in [(4u8, 2i16), (7, 3), (20, 10)] {
            assert_eq!(
                super::cavalier_expert_trainer_bonus(level),
                expected,
                "level {level} Expert Trainer: level/2"
            );
        }
    }

    /// Both feat counts, across their real step boundaries.
    #[test]
    fn the_two_feat_counts_step_at_their_real_levels() {
        for (level, expected) in [(1u8, 0i16), (5, 0), (6, 1), (11, 1), (12, 2), (18, 3), (20, 3)] {
            assert_eq!(
                super::cavalier_bonus_combat_feat_count(level),
                expected,
                "level {level} bonus combat feats: level/6"
            );
        }
        for (level, expected) in [(1u8, 1i16), (8, 1), (9, 2), (16, 2), (17, 3), (20, 3)] {
            assert_eq!(
                super::cavalier_teamwork_feat_count(level),
                expected,
                "level {level} teamwork feats: Tactician 1st / 9th / 17th"
            );
        }
    }

    /// Order of the Sword grounds only when explicitly chosen, and
    /// clears the order-powers block when it is.
    #[test]
    fn order_of_the_sword_grounds_only_when_explicitly_recorded() {
        let bare = build_pilot_headless_receipt(&cavalier(1));
        assert!(
            bare.computation
                .diagnostics
                .iter()
                .any(|d| d.id == "class_feature.apg.cavalier.order_powers.unsupported"
                    && d.claim_blocking),
            "a Cavalier with no recorded Order stays blocked on it: {:?}",
            bare.computation.diagnostics
        );

        let mut sworn = cavalier(1);
        sworn.chosen.selected_choices.push(SelectedChoice {
            choice_set_id: CAVALIER_ORDER_CHOICE_ID.to_owned(),
            selection_id: ORDER_OF_THE_SWORD_SELECTION.to_owned(),
        });
        let receipt = build_pilot_headless_receipt(&sworn);
        assert!(
            !receipt
                .computation
                .diagnostics
                .iter()
                .any(|d| d.id == "class_feature.apg.cavalier.order_powers.unsupported"),
            "a recognized Order clears the block: {:?}",
            receipt.computation.diagnostics
        );
        // 1/2 level, minimum +1: the floor is what applies at level 1.
        assert_eq!(
            value(&sworn, "class_feature.apg.cavalier.order_of_the_sword.sense_motive_bonus"),
            Some(1)
        );
        for (level, expected) in [(1u8, 1i16), (2, 1), (4, 2), (11, 5), (20, 10)] {
            assert_eq!(
                super::cavalier_order_of_the_sword_sense_motive_bonus(level),
                expected,
                "level {level}: max(1, level/2)"
            );
        }
    }

    /// Cavalier's real CSKILL list includes all three tracked skills.
    #[test]
    fn cavalier_earns_the_class_skill_bonus_on_all_three_tracked_skills() {
        let receipt = build_pilot_headless_receipt(&cavalier(1));
        for skill in ["climb", "intimidate", "swim"] {
            let record = receipt
                .computation
                .explanations
                .iter()
                .find(|e| e.id == format!("skill.selected_modifier.{skill}"))
                .unwrap_or_else(|| panic!("{skill} must be computed"));
            assert!(
                record.detail.contains("class-skill bonus (+3)"),
                "{skill} is on Cavalier's real CSKILL list: {record:?}"
            );
        }
    }

    /// No Cavalier diagnostic may still assert the class has no
    /// class-skill list -- it has one, and that text was false.
    #[test]
    fn no_cavalier_diagnostic_claims_the_class_has_no_class_skill_list() {
        for diagnostic in &build_pilot_headless_receipt(&cavalier(1)).computation.diagnostics {
            assert!(
                !diagnostic.message.contains("no class-skill list"),
                "Cavalier DOES have a class-skill list: {diagnostic:?}"
            );
        }
    }
}

/// v0.6 alpha swarm, task #14 (Swashbuckler, 2026-07-27): Finesse's
/// prerequisite substitution, Weapon Training, and the Bonus Feats
/// level-equivalence fact.
#[cfg(test)]
mod swashbuckler_finesse_tests {
    use super::{
        build_pilot_headless_receipt, CharacterClassLevel, CharacterInput, SWASHBUCKLER_CLASS_ID,
    };
    use crate::rules_core::character_input::load_character_input_fixture;

    const FIGHTER_LEVEL_1_FIXTURE: &str = include_str!(
        "../../tests/fixtures/rules_core/pf1_human_fighter_level1_ge06_deterministic_input.txt"
    );

    fn swashbuckler(level: u8) -> CharacterInput {
        let result = load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE);
        let mut input = result.character_input.expect("valid fixture");
        input.chosen.class_levels =
            vec![CharacterClassLevel { class_id: SWASHBUCKLER_CLASS_ID.to_owned(), level }];
        input
    }

    fn value(input: &CharacterInput, id: &str) -> Option<i16> {
        build_pilot_headless_receipt(input)
            .computation
            .explanations
            .iter()
            .find(|e| e.id == id)
            .map(|e| e.value)
    }

    /// Finesse takes `max(CHASCORE, INTSCORE)` -- the max of two real
    /// ability SCORES, unlike Brawler's Cunning which floors INT at the
    /// constant 13. The shared helper must handle both without either
    /// class borrowing the other's operand.
    #[test]
    fn finesse_substitutes_the_higher_of_charisma_and_intelligence_scores() {
        for (charisma, intelligence, expected) in
            [(18, 10, 18), (10, 18, 18), (7, 7, 7), (13, 13, 13), (20, 3, 20)]
        {
            assert_eq!(
                super::effective_combat_feat_intelligence_score(charisma, intelligence),
                expected,
                "max(CHA {charisma}, INT {intelligence})"
            );
        }
    }

    /// Brawler's own Cunning must be unchanged by the generalization --
    /// it floors at the constant 13, which is NOT what Finesse does.
    #[test]
    fn brawler_cunning_still_floors_intelligence_at_thirteen() {
        for (intelligence, expected) in [(7, 13), (12, 13), (13, 13), (18, 18)] {
            assert_eq!(
                super::brawler_cunning_effective_intelligence_score(intelligence),
                expected,
                "Brawler floors INT {intelligence} at 13"
            );
        }
    }

    /// Finesse grounds unconditionally from level 1. Fixture CHA 8,
    /// INT 10 -> max is 10.
    #[test]
    fn finesse_grounds_the_effective_score_from_first_level() {
        assert_eq!(
            value(
                &swashbuckler(1),
                "class_feature.acg.swashbuckler.finesse_effective_intelligence_for_combat_feats"
            ),
            Some(10),
            "fixture CHA 8 / INT 10 -> effective 10"
        );
    }

    /// Weapon Training is `(level-1)/4`: +1 at 5th, +2 at 9th, +3 at
    /// 13th, +4 at 17th, and genuinely 0 below 5th.
    #[test]
    fn weapon_training_bonus_matches_the_corpus_formula_at_every_level() {
        for (level, expected) in [
            (1u8, 0i16),
            (4, 0),
            (5, 1),
            (8, 1),
            (9, 2),
            (12, 2),
            (13, 3),
            (16, 3),
            (17, 4),
            (20, 4),
        ] {
            assert_eq!(
                super::swashbuckler_weapon_training_bonus(level),
                expected,
                "level {level}: (level - 1)/4"
            );
        }
    }

    /// Swashbuckler levels count as fighter levels for feat
    /// qualification -- the fact grounds, the prereq wiring stays
    /// deferred (the Martial Training ruling).
    #[test]
    fn bonus_feats_ground_the_fighter_level_equivalence_fact() {
        assert_eq!(
            value(
                &swashbuckler(1),
                "class_feature.acg.swashbuckler.fighter_level_equivalence_for_feats"
            ),
            Some(1)
        );
    }

    /// None of the three leaks onto a non-Swashbuckler.
    #[test]
    fn none_of_the_three_grounds_for_a_non_swashbuckler() {
        let result = load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE);
        let fighter = result.character_input.expect("valid fixture");
        for id in [
            "class_feature.acg.swashbuckler.finesse_effective_intelligence_for_combat_feats",
            "class_feature.acg.swashbuckler.weapon_training_bonus",
            "class_feature.acg.swashbuckler.fighter_level_equivalence_for_feats",
        ] {
            assert_eq!(value(&fighter, id), None, "{id} must not ground for a Fighter");
        }
    }

    /// The six deeds carrying real magnitudes, each at its own corpus
    /// tier. Tier gating uses `SwashbucklerLVL` rather than the corpus's
    /// own `SwashbucklerDeedQualifyLVL`, which is never populated for
    /// this class -- see `swashbuckler_deed_tier_reached` for the full
    /// reasoning and the lead's ruling.
    #[test]
    fn deed_tiers_gate_on_swashbuckler_level_because_the_corpus_gate_is_unpopulated() {
        for (tier, first_level) in [(1u8, 1u8), (3, 3), (7, 7), (11, 11), (15, 15), (19, 19)] {
            assert!(
                !super::swashbuckler_deed_tier_reached(first_level - 1, tier)
                    || first_level == 1,
                "tier {tier} must not be reached below level {first_level}"
            );
            assert!(
                super::swashbuckler_deed_tier_reached(first_level, tier),
                "tier {tier} is reached at level {first_level}"
            );
            assert!(super::swashbuckler_deed_tier_reached(20, tier), "tier {tier} at level 20");
        }
    }

    /// Tier-1 deeds: Derring-Do's uses equal the Dexterity MODIFIER and
    /// Dodging Panache's dodge bonus equals the Charisma modifier. The
    /// fixture's Charisma 8 gives a genuinely negative -1, which is
    /// reported honestly rather than floored.
    #[test]
    fn tier_one_deeds_ground_their_real_ability_derived_magnitudes() {
        let receipt = build_pilot_headless_receipt(&swashbuckler(1));
        let find = |id: &str| {
            receipt.computation.explanations.iter().find(|e| e.id == id).map(|e| e.value)
        };
        // Fixture DEX 14 -> +2, CHA 8 -> -1.
        assert_eq!(find("class_feature.acg.swashbuckler.derring_do_uses_per_day"), Some(2));
        assert_eq!(find("class_feature.acg.swashbuckler.dodging_panache_dodge_bonus"), Some(-1));
    }

    /// Precise Strike is a weapon-damage magnitude equal to swashbuckler
    /// level, doubled on a critical -- the Bomb/Sacred-Weapon idiom.
    /// Tier 3, so absent at levels 1-2.
    #[test]
    fn precise_strike_grounds_from_tier_three_and_doubles_on_a_critical() {
        for level in [1u8, 2] {
            let receipt = build_pilot_headless_receipt(&swashbuckler(level));
            assert!(
                !receipt
                    .computation
                    .explanations
                    .iter()
                    .any(|e| e.id.contains("precise_strike")),
                "level {level} is below Precise Strike's tier"
            );
        }
        for level in [3u8, 10, 20] {
            let receipt = build_pilot_headless_receipt(&swashbuckler(level));
            let find = |id: &str| {
                receipt.computation.explanations.iter().find(|e| e.id == id).map(|e| e.value)
            };
            assert_eq!(
                find("class_feature.acg.swashbuckler.precise_strike_damage"),
                Some(i16::from(level))
            );
            assert_eq!(
                find("class_feature.acg.swashbuckler.precise_strike_critical_damage"),
                Some(2 * i16::from(level))
            );
        }
    }

    /// The two tier-19 stab DCs share a byte-identical formula
    /// (`level/2 + 10 + DEX`), and Bleeding Wound arrives at tier 11.
    #[test]
    fn high_tier_deeds_ground_at_their_own_gates() {
        let mid = build_pilot_headless_receipt(&swashbuckler(11));
        assert_eq!(
            mid.computation
                .explanations
                .iter()
                .find(|e| e.id == "class_feature.acg.swashbuckler.bleeding_wound_damage")
                .map(|e| e.value),
            Some(2),
            "Bleeding Wound bleeds the Dexterity modifier"
        );
        assert!(
            !mid.computation.explanations.iter().any(|e| e.id.contains("stab")),
            "the stab deeds are tier 19, not 11"
        );

        let top = build_pilot_headless_receipt(&swashbuckler(19));
        // 19/2 + 10 + 2 = 9 + 12 = 21.
        for id in [
            "class_feature.acg.swashbuckler.deadly_stab_dc",
            "class_feature.acg.swashbuckler.stunning_stab_dc",
        ] {
            assert_eq!(
                top.computation.explanations.iter().find(|e| e.id == id).map(|e| e.value),
                Some(21),
                "{id}: level/2 + 10 + DEX"
            );
        }
        assert_eq!(super::swashbuckler_stab_save_dc(19, 2), 21);
        assert_eq!(super::swashbuckler_stab_save_dc(20, 0), 20);
    }

    /// No deed leaks onto a non-Swashbuckler.
    #[test]
    fn deeds_never_ground_for_a_non_swashbuckler() {
        let result = load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE);
        let fighter = result.character_input.expect("valid fixture");
        let receipt = build_pilot_headless_receipt(&fighter);
        for fragment in ["derring_do", "dodging_panache", "precise_strike", "bleeding_wound", "stab"] {
            assert!(
                !receipt.computation.explanations.iter().any(|e| e.id.contains(fragment)),
                "a Fighter must not ground {fragment}"
            );
        }
    }
}


/// v0.6 alpha swarm, task #17 (Summoner bounded Eidolon MVP,
/// 2026-07-27): the canonical Quadruped Eidolon's corpus-derived stat
/// block, plus the evolution-point pool whose spending stays deferred.
#[cfg(test)]
mod summoner_eidolon_tests {
    use super::{build_pilot_headless_receipt, CharacterClassLevel, CharacterInput,
        SUMMONER_CLASS_ID};
    use crate::rules_core::character_input::load_character_input_fixture;

    const FIGHTER_LEVEL_1_FIXTURE: &str = include_str!(
        "../../tests/fixtures/rules_core/pf1_human_fighter_level1_ge06_deterministic_input.txt"
    );

    fn summoner(level: u8) -> CharacterInput {
        let result = load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE);
        let mut input = result.character_input.expect("valid fixture");
        input.chosen.class_levels =
            vec![CharacterClassLevel { class_id: SUMMONER_CLASS_ID.to_owned(), level }];
        input
    }

    fn value(input: &CharacterInput, id: &str) -> Option<i16> {
        build_pilot_headless_receipt(input)
            .computation
            .explanations
            .iter()
            .find(|e| e.id == id)
            .map(|e| e.value)
    }

    /// The evolution-point pool, re-derived level by level from the
    /// corpus formula's own `>=` terms rather than copied from the
    /// published table.
    #[test]
    fn evolution_pool_matches_the_corpus_formula_at_every_level() {
        let expected = [
            3, 4, 5, 7, 8, 9, 10, 11, 13, 14, 15, 16, 17, 19, 20, 21, 22, 23, 25, 26,
        ];
        for (index, want) in expected.iter().enumerate() {
            let level = (index + 1) as u8;
            assert_eq!(
                super::eidolon_evolution_pool(level),
                *want,
                "summoner level {level} evolution points"
            );
        }
    }

    /// Natural armor steps +2 at eight specific master levels.
    #[test]
    fn eidolon_natural_armor_steps_at_its_eight_corpus_gates() {
        for (level, want) in [
            (1u8, 0i16),
            (2, 2),
            (4, 2),
            (5, 4),
            (7, 6),
            (10, 8),
            (12, 10),
            (15, 12),
            (17, 14),
            (20, 16),
        ] {
            assert_eq!(
                super::eidolon_natural_armor_bonus(level),
                want,
                "level {level} natural armor bonus (on top of the racial +2)"
            );
        }
    }

    /// Max natural attacks: 3, then +1 at 4/9/14/19.
    #[test]
    fn eidolon_max_natural_attacks_steps_at_four_nine_fourteen_nineteen() {
        for (level, want) in
            [(1u8, 3i16), (3, 3), (4, 4), (8, 4), (9, 5), (13, 5), (14, 6), (18, 6), (19, 7), (20, 7)]
        {
            assert_eq!(super::eidolon_max_natural_attacks(level), want, "level {level}");
        }
    }

    /// The Eidolon has FULL base attack bonus (`classlevel`), unlike the
    /// Wolf companion's 3/4 -- the single most important reason the Wolf
    /// function could not be reused.
    #[test]
    fn eidolon_base_attack_bonus_is_full_not_three_quarters() {
        for level in [1u8, 5, 11, 20] {
            assert_eq!(
                super::eidolon_base_attack_bonus(level),
                i16::from(level),
                "level {level}: full BAB"
            );
        }
    }

    /// A level-1 Quadruped Eidolon's whole stat block grounds, and the
    /// pool is reported without pretending any of it is spent.
    #[test]
    fn a_level_one_quadruped_eidolon_grounds_its_real_stat_block() {
        let input = summoner(1);
        for (id, want) in [
            ("class_feature.apg.summoner.eidolon.evolution_pool", 3),
            ("class_feature.apg.summoner.eidolon.base_attack_bonus", 1),
            ("class_feature.apg.summoner.eidolon.natural_armor_bonus", 0),
            ("class_feature.apg.summoner.eidolon.max_natural_attacks", 3),
            ("class_feature.apg.summoner.eidolon.base_land_speed", 40),
            ("class_feature.apg.summoner.eidolon.bite_damage_die", 6),
        ] {
            assert_eq!(value(&input, id), Some(want), "{id}");
        }
    }

    /// Summoner stays Blocked on unspent evolutions -- the MVP grounds
    /// the pool SIZE, never its expenditure.
    #[test]
    fn summoner_stays_blocked_on_unspent_evolutions_at_every_level() {
        for level in [1u8, 10, 20] {
            let receipt = build_pilot_headless_receipt(&summoner(level));
            assert_eq!(
                receipt.status,
                super::HeadlessReceiptStatus::Blocked,
                "level {level} Summoner must stay Blocked"
            );
            assert!(
                receipt.computation.diagnostics.iter().any(|d| {
                    d.id == "class_feature.apg.summoner.eidolon.evolutions_deferred.unsupported"
                        && d.claim_blocking
                }),
                "level {level} must carry the claim-blocking evolutions_deferred diagnostic: {:?}",
                receipt.computation.diagnostics
            );
        }
    }

    /// The Eidolon's records never leak onto a non-Summoner.
    #[test]
    fn eidolon_records_never_ground_for_a_non_summoner() {
        let result = load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE);
        let fighter = result.character_input.expect("valid fixture");
        assert!(
            !build_pilot_headless_receipt(&fighter)
                .computation
                .explanations
                .iter()
                .any(|e| e.id.contains("eidolon")),
            "a Fighter must ground no Eidolon record"
        );
    }
}

/// v0.6 alpha swarm, task #22 (2026-07-27): the eight `feat_effects`
/// producers that were built, tested, and consumed by nothing.
///
/// Only ONE has a real computed total to land on -- Toughness, whose
/// hit-point bonus goes into the Fighter level-1 hit-point record that
/// already named "Toughness / feat hit-point interplay" as its own
/// documented gap. The other seven target dimensions this engine
/// computes nowhere (initiative, non-skill checks, combat maneuvers,
/// unarmed strikes, movement), so they ground as standalone records
/// under the corrected bar rather than being left inert.
#[cfg(test)]
mod orphan_feat_producer_consumer_tests {
    use super::{build_pilot_headless_receipt, CharacterInput};
    use crate::rules_core::character_input::load_character_input_fixture;

    const FIGHTER_LEVEL_1_FIXTURE: &str = include_str!(
        "../../tests/fixtures/rules_core/pf1_human_fighter_level1_ge06_deterministic_input.txt"
    );

    fn fighter() -> CharacterInput {
        load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE)
            .character_input
            .expect("valid fixture")
    }

    fn value(input: &CharacterInput, id: &str) -> Option<i16> {
        build_pilot_headless_receipt(input)
            .computation
            .explanations
            .iter()
            .find(|e| e.id == id)
            .map(|e| e.value)
    }

    /// Toughness is the one orphan with a real total. Proven by
    /// differencing the same character with and without it, so the
    /// assertion cannot pass on a standalone record alone.
    #[test]
    fn toughness_actually_raises_the_real_fighter_hit_point_total() {
        let without = value(&fighter(), "class_chassis.fighter.level_1_hit_points")
            .expect("fighter level-1 hit points must be computed");

        let mut with = fighter();
        with.chosen.selected_feats.push("Toughness".to_owned());
        let raised = value(&with, "class_chassis.fighter.level_1_hit_points")
            .expect("hit points must still be computed");

        assert_eq!(raised - without, 3, "Toughness grants +3 hit points at low level");
    }

    /// The seven producers with no total to land on must still be
    /// consumed -- grounded as standalone records rather than left
    /// inert. Each keys on a feat the fixture does not have, so absence
    /// is the baseline.
    #[test]
    fn the_seven_totalless_producers_ground_standalone_records_when_their_feat_is_present() {
        for (feat, id, want) in [
            ("Improved Initiative", "feat.standalone.initiative_bonus", 4),
            ("Endurance", "feat.standalone.endurance_check_bonus", 4),
            ("Fleet", "feat.standalone.base_speed_bonus", 5),
            ("Nimble Moves", "feat.standalone.difficult_terrain_feet", 5),
        ] {
            let mut input = fighter();
            assert_eq!(value(&input, id), None, "{id} must be absent without {feat}");
            input.chosen.selected_feats.push(feat.to_owned());
            assert_eq!(value(&input, id), Some(want), "{feat} -> {id}");
        }
    }

    /// Improved Bull Rush grounds both its CMB and CMD halves; the
    /// Greater variants genuinely carry no CMD term.
    #[test]
    fn combat_maneuver_feats_ground_their_cmb_and_cmd_halves() {
        let mut input = fighter();
        input.chosen.selected_feats.push("Improved Bull Rush".to_owned());
        assert_eq!(value(&input, "feat.standalone.combat_maneuver.bull_rush.cmb"), Some(2));
        assert_eq!(value(&input, "feat.standalone.combat_maneuver.bull_rush.cmd"), Some(2));
    }

    /// Stunning Fist reaches its producer through the class-granted feat
    /// path -- a Monk never has it in `selected_feats`.
    #[test]
    fn a_monk_grounds_stunning_fist_without_ever_selecting_the_feat() {
        let mut monk = fighter();
        monk.chosen.class_levels =
            vec![super::CharacterClassLevel { class_id: "class:monk".to_owned(), level: 4 }];
        assert!(
            !monk.chosen.selected_feats.iter().any(|f| f == "Stunning Fist"),
            "the Monk must not have selected it -- the grant is what is under test"
        );
        // Fixture Wisdom 12 (+1): DC = 10 + 4/2 + 1 = 13.
        assert_eq!(value(&monk, "feat.standalone.stunning_fist.save_dc"), Some(13));
        assert_eq!(value(&monk, "feat.standalone.stunning_fist.uses_per_day"), Some(4));
    }

    /// Weapon Focus was the LAST orphan -- missed by my own #22 sweep
    /// because I re-used a producer inventory taken during #20 instead of
    /// re-enumerating it, and `feat_effects.rs` gained producers in
    /// between. Found by the lead cross-checking all 13 producers rather
    /// than the 8 I had listed.
    ///
    /// Wiring it is a REAL behavior change rather than latent capability:
    /// this repo's own deterministic Fighter fixture already carries
    /// Weapon Focus (Longsword) through the legacy compound id
    /// (`choice:fighter_bonus_feat -> feat:weapon_focus:weapon:longsword`),
    /// which the producer deliberately accepts so the shipped loadout
    /// grounds something. So the fixture Fighter gains a record it never
    /// had before this commit.
    #[test]
    fn the_shipped_fighter_fixture_now_grounds_its_weapon_focus_longsword() {
        assert_eq!(
            value(&fighter(), "feat.standalone.weapon_focus.longsword"),
            Some(1),
            "the real fixture Fighter has Weapon Focus (Longsword) via the legacy compound id"
        );
    }

    /// Greater Weapon Focus stacks with Weapon Focus on the same weapon
    /// for a genuine +2, and the two sources are deduplicated to a
    /// single record rather than emitting one each.
    #[test]
    fn greater_weapon_focus_stacks_to_two_on_the_same_weapon_without_duplicating() {
        let mut input = fighter();
        input.chosen.selected_feats.push("Greater Weapon Focus".to_owned());
        input.chosen.selected_choices.push(
            crate::rules_core::character_input::SelectedChoice {
                choice_set_id: "choice:greater_weapon_focus_target".to_owned(),
                selection_id: "weapon:longsword".to_owned(),
            },
        );
        assert_eq!(value(&input, "feat.standalone.weapon_focus.longsword"), Some(2));

        let count = build_pilot_headless_receipt(&input)
            .computation
            .explanations
            .iter()
            .filter(|e| e.id == "feat.standalone.weapon_focus.longsword")
            .count();
        assert_eq!(count, 1, "the two sources must dedup into one record per weapon");
    }

    /// Spell Focus grounds per chosen school. It is NOT integrated into
    /// the per-spell-level save-DC records: those are keyed by spell
    /// level while Spell Focus is keyed by school, so there is no
    /// matching total to layer it onto without inventing a mapping.
    #[test]
    fn spell_focus_grounds_per_school_and_is_not_folded_into_level_keyed_dcs() {
        let mut input = fighter();
        input.chosen.selected_feats.push("Spell Focus".to_owned());
        input.chosen.selected_choices.push(
            crate::rules_core::character_input::SelectedChoice {
                choice_set_id: "choice:spell_focus_target".to_owned(),
                selection_id: "school:evocation".to_owned(),
            },
        );
        assert_eq!(value(&input, "feat.standalone.spell_focus.evocation"), Some(1));
    }
}

/// v0.6 alpha swarm, task #5 (Brawler's six remaining real features,
/// 2026-07-27).
#[cfg(test)]
mod brawler_remaining_feature_tests {
    use super::{build_pilot_headless_receipt, CharacterClassLevel, CharacterInput,
        BRAWLER_CLASS_ID};
    use crate::rules_core::character_input::load_character_input_fixture;

    const FIGHTER_LEVEL_1_FIXTURE: &str = include_str!(
        "../../tests/fixtures/rules_core/pf1_human_fighter_level1_ge06_deterministic_input.txt"
    );

    fn brawler(level: u8) -> CharacterInput {
        let result = load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE);
        let mut input = result.character_input.expect("valid fixture");
        input.chosen.class_levels =
            vec![CharacterClassLevel { class_id: BRAWLER_CLASS_ID.to_owned(), level }];
        input
    }

    fn value(input: &CharacterInput, id: &str) -> Option<i16> {
        build_pilot_headless_receipt(input)
            .computation
            .explanations
            .iter()
            .find(|e| e.id == id)
            .map(|e| e.value)
    }

    /// Maneuver Training is set by TWO stacking corpus lines: the
    /// `(L>2)+(L>6)+(L>10)+(L>14)` line tops out at 4, and a separate
    /// `1|PREVARGT:BrawlerLVL,18` supplies the 5th. Reading only the
    /// first gives 4 at levels 19-20 instead of 5.
    ///
    /// The corpus itself corroborates this: it carries the author's
    /// comment on a rejected single-line variant saying it "never got
    /// BrawlerManeuverTraining up to 5".
    #[test]
    fn maneuver_training_count_reaches_five_via_its_second_corpus_line() {
        for (level, want) in [
            (1u8, 0i16), (2, 0), (3, 1), (6, 1), (7, 2), (10, 2), (11, 3),
            (14, 3), (15, 4), (18, 4), (19, 5), (20, 5),
        ] {
            assert_eq!(super::brawler_maneuver_training_count(level), want, "level {level}");
        }
    }

    /// Knockout's stat bonus is `max(STR,DEX)` -- BARE tokens, i.e.
    /// ability MODIFIERS, unlike Brawler's Cunning's explicit
    /// `INTSCORE`. The corpus disambiguates deliberately, and a DC built
    /// from scores instead of modifiers would be wildly wrong.
    #[test]
    fn knockout_uses_ability_modifiers_not_scores_unlike_brawlers_cunning() {
        // Fixture STR 16 (+3), DEX 14 (+2) -> max modifier 3.
        assert_eq!(super::brawler_knockout_stat_bonus(3, 2), 3);
        assert_eq!(super::brawler_knockout_stat_bonus(-1, 4), 4);
        // Level 4 DC: 4/2 + 10 + 3 = 15. A score-based read would give 26.
        assert_eq!(super::brawler_knockout_dc(4, 3), 15);
        assert_eq!(super::brawler_knockout_dc(20, 5), 25);
        // Cunning still floors a SCORE at 13 -- the two must not converge.
        assert_eq!(super::brawler_cunning_effective_intelligence_score(10), 13);
    }

    /// Knockout is granted at 4th, not 5th, and `(L+2)/6` yields exactly
    /// 1 there -- the corpus is internally consistent.
    #[test]
    fn knockout_uses_per_day_matches_its_fourth_level_grant() {
        for (level, want) in [(4u8, 1i16), (9, 1), (10, 2), (16, 3), (20, 3)] {
            assert_eq!(super::brawler_knockout_uses_per_day(level), want, "level {level}");
        }
        assert_eq!(value(&brawler(1), "class_feature.acg.brawler.knockout_dc"), None);
        assert_eq!(value(&brawler(4), "class_feature.acg.brawler.knockout_dc"), Some(15));
    }

    /// Flurry's extra attacks, and its self-applied attack penalty --
    /// a real corpus token, unlike Cavalier's DESC-only one.
    ///
    /// Note the corpus `min(...,3)` cap is NOT meaningfully covered
    /// here, and cannot be: `(20+6)/7` is already 3, so the cap never
    /// binds for any reachable level. Asserting the values is the most
    /// this test can honestly do.
    #[test]
    fn brawlers_flurry_extra_attacks_cap_at_three() {
        for (level, want) in [(2u8, 1i16), (7, 1), (8, 2), (14, 2), (15, 3), (20, 3)] {
            assert_eq!(super::brawler_flurry_extra_attacks(level), want, "level {level}");
        }
        assert_eq!(
            value(&brawler(2), "class_feature.acg.brawler.flurry_attack_penalty"),
            Some(-2)
        );
        assert_eq!(value(&brawler(1), "class_feature.acg.brawler.flurry_extra_attacks"), None);
    }

    /// Bonus Feats: `(1+level)/3`. Seven archetype `-1` deductions exist
    /// in the corpus but are provably vacuous here -- their only setter
    /// is the Wild Child archetype, and this repo ingests no Brawler
    /// archetype at all.
    #[test]
    fn bonus_feat_count_ignores_the_seven_vacuous_archetype_deductions() {
        for (level, want) in [(1u8, 0i16), (2, 1), (4, 1), (5, 2), (8, 3), (11, 4), (20, 7)] {
            assert_eq!(super::brawler_bonus_feat_count(level), want, "level {level}");
        }
    }

    /// Martial Flexibility's uses/day pool, granted 1st.
    #[test]
    fn martial_flexibility_pool_grounds_from_first_level() {
        for (level, want) in [(1u8, 4i16), (2, 4), (4, 5), (10, 8), (20, 13)] {
            assert_eq!(super::brawler_martial_flexibility_uses(level), want, "level {level}");
        }
        assert_eq!(
            value(&brawler(1), "class_feature.acg.brawler.martial_flexibility_uses_per_day"),
            Some(4)
        );
    }

    /// Martial Training grounds three level-equivalence facts. Brawler's
    /// feature shares a NAME with Alchemist's, which is a genuine no-op
    /// with zero tokens -- same name, different class, opposite verdict.
    #[test]
    fn martial_training_grounds_its_three_level_equivalence_facts() {
        for id in [
            "class_feature.acg.brawler.martial_training.fighter_level_equivalence",
            "class_feature.acg.brawler.martial_training.monk_level_equivalence",
            "class_feature.acg.brawler.martial_training.monk_feat_qualify",
        ] {
            assert_eq!(value(&brawler(7), id), Some(7), "{id}");
        }
    }

    /// Nothing leaks onto a non-Brawler.
    #[test]
    fn none_of_the_six_grounds_for_a_non_brawler() {
        let fighter = load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE)
            .character_input
            .expect("valid fixture");
        for frag in ["knockout", "flurry", "martial_flexibility", "martial_training",
            "maneuver_training", "bonus_feat_count"] {
            assert!(
                !build_pilot_headless_receipt(&fighter)
                    .computation
                    .explanations
                    .iter()
                    .any(|e| e.id.contains(&format!("brawler.{frag}"))),
                "a Fighter must not ground brawler.{frag}"
            );
        }
    }
}

/// v0.6 alpha swarm, Tier 0 of the opponent-interaction architecture
/// work (2026-07-27, risks item 52): the four target-conditioned
/// features whose formulas turn out to read only the character's OWN
/// level, needing no opponent-tracking pillar at all.
#[cfg(test)]
mod opponent_conditioned_tier_zero_tests {
    use super::{build_pilot_headless_receipt, CharacterClassLevel, CharacterInput,
        ActiveState, CAVALIER_CHALLENGE_ABILITY_ID, CAVALIER_CLASS_ID, INVESTIGATOR_CLASS_ID,
        INVESTIGATOR_STUDIED_DEFENSE_CHOICE_ID, INVESTIGATOR_STUDIED_DEFENSE_SELECTION,
        SLAYER_CLASS_ID};
    use crate::rules_core::character_input::{
        load_character_input_fixture, ClassAbilityActivation, SelectedChoice,
    };

    const FIGHTER_LEVEL_1_FIXTURE: &str = include_str!(
        "../../tests/fixtures/rules_core/pf1_human_fighter_level1_ge06_deterministic_input.txt"
    );

    fn character(class_id: &str, level: u8) -> CharacterInput {
        let mut input = load_character_input_fixture(FIGHTER_LEVEL_1_FIXTURE)
            .character_input
            .expect("valid fixture");
        input.chosen.class_levels =
            vec![CharacterClassLevel { class_id: class_id.to_owned(), level }];
        input
    }

    fn value(input: &CharacterInput, id: &str) -> Option<i16> {
        build_pilot_headless_receipt(input)
            .computation
            .explanations
            .iter()
            .find(|e| e.id == id)
            .map(|e| e.value)
    }

    /// Studied Target: `SlayerLVL/5 + 1`, and the simultaneous-target
    /// count `(L>0)+(L>6)` -- one target from 1st, two from 7th.
    #[test]
    fn slayer_studied_target_bonus_and_target_count_match_the_corpus() {
        for (level, want) in [(1u8, 1i16), (4, 1), (5, 2), (9, 2), (10, 3), (20, 5)] {
            assert_eq!(super::slayer_studied_target_bonus(level), want, "level {level}");
        }
        for (level, want) in [(1u8, 1i16), (6, 1), (7, 2), (20, 2)] {
            assert_eq!(super::slayer_studied_target_count(level), want, "level {level}");
        }
        assert_eq!(value(&character(SLAYER_CLASS_ID, 5), "class_feature.acg.slayer.studied_target_bonus"), Some(2));
        assert_eq!(value(&character(SLAYER_CLASS_ID, 7), "class_feature.acg.slayer.studied_target_count"), Some(2));
    }




    /// The shared Witch hex save DC: `10 + INT + WitchLVL/2`. Every one
    /// of the 27 hex records aliases this single variable
    /// (`WitchHexDC_<Name>|WitchHexDC`), so it is ONE mechanism, not 27.
    #[test]
    fn the_witch_hex_save_dc_is_one_shared_formula_across_every_hex() {
        for (level, intelligence, want) in
            [(1u8, 0i16, 10i16), (1, 4, 14), (2, 4, 15), (10, 4, 19), (20, 5, 25)]
        {
            assert_eq!(super::witch_hex_save_dc(level, intelligence), want, "level {level}");
        }
        // Fixture INT 10 -> modifier 0; level 6 -> 10 + 0 + 3 = 13.
        assert_eq!(value(&character("class:witch", 6), "class_feature.apg.witch.hex_save_dc"), Some(13));
    }

    /// Cauldron and Flight are the only two hexes carrying a magnitude
    /// distinct from the shared DC. Each needs an explicit pick.
    #[test]
    fn cauldron_and_flight_ground_their_own_distinct_magnitudes_when_chosen() {
        let bare = character("class:witch", 6);
        assert_eq!(value(&bare, "class_feature.apg.witch.cauldron_hex.craft_alchemy_bonus"), None);

        let mut cauldron = bare.clone();
        cauldron.chosen.selected_choices.push(SelectedChoice {
            choice_set_id: super::WITCH_HEX_CHOICE_ID.to_owned(),
            selection_id: super::CAULDRON_HEX_SELECTION.to_owned(),
        });
        assert_eq!(
            value(&cauldron, "class_feature.apg.witch.cauldron_hex.craft_alchemy_bonus"),
            Some(4)
        );
    }

    /// Flight's `+4 Swim` is the standout: Swim IS one of the three
    /// skills this engine computes, so it INTEGRATES into the real
    /// total. Proven by differencing the same character with and without
    /// the hex, so the assertion cannot pass on a standalone record.
    #[test]
    fn the_flight_hex_actually_raises_the_real_computed_swim_total() {
        let without = character("class:witch", 6);
        let base = value(&without, "skill.selected_modifier.swim")
            .expect("swim modifier must be computed for a Witch");

        let mut with = without.clone();
        with.chosen.selected_choices.push(SelectedChoice {
            choice_set_id: super::WITCH_HEX_CHOICE_ID.to_owned(),
            selection_id: super::FLIGHT_HEX_SELECTION.to_owned(),
        });
        let raised = value(&with, "skill.selected_modifier.swim").expect("still computed");

        assert_eq!(raised - base, 4, "the Flight hex is worth 4 real Swim");
    }

    /// Neither hex leaks onto a non-Witch, and Flight must not move a
    /// non-Witch's Swim total.
    #[test]
    fn the_hexes_never_apply_to_a_non_witch() {
        let mut fighter = character("class:fighter", 6);
        let clean_swim = value(&fighter, "skill.selected_modifier.swim");
        fighter.chosen.selected_choices.push(SelectedChoice {
            choice_set_id: super::WITCH_HEX_CHOICE_ID.to_owned(),
            selection_id: super::FLIGHT_HEX_SELECTION.to_owned(),
        });
        assert_eq!(
            value(&fighter, "skill.selected_modifier.swim"),
            clean_swim,
            "a Fighter's Swim must be untouched by a spoofed Witch hex"
        );
        assert_eq!(value(&fighter, "class_feature.apg.witch.hex_save_dc"), None);
    }

    /// The familiar's master benefit grounds only on an explicit species
    /// pick, and only for a class that actually gets a familiar.
    #[test]
    fn the_familiar_benefit_needs_both_a_familiar_class_and_an_explicit_pick() {
        let mut witch = character("class:witch", 5);
        assert_eq!(
            value(&witch, "class_feature.familiar.master_hit_point_bonus"),
            None,
            "no familiar is seeded"
        );
        witch.chosen.selected_choices.push(SelectedChoice {
            choice_set_id: super::FAMILIAR_CHOICE_ID.to_owned(),
            selection_id: super::FAMILIAR_TOAD_SELECTION.to_owned(),
        });
        assert_eq!(value(&witch, "class_feature.familiar.master_hit_point_bonus"), Some(3));

        // Same pick on a class with no familiar grounds nothing.
        let mut fighter = character("class:fighter", 5);
        fighter.chosen.selected_choices.push(SelectedChoice {
            choice_set_id: super::FAMILIAR_CHOICE_ID.to_owned(),
            selection_id: super::FAMILIAR_TOAD_SELECTION.to_owned(),
        });
        assert_eq!(value(&fighter, "class_feature.familiar.master_hit_point_bonus"), None);
    }

    /// One implementation closes the familiar slot for BOTH classes --
    /// the corpus routes Shaman's Spirit Animal through the same
    /// `Standard Familiar List` as Witch's Familiar (corpus-first, per
    /// the lead's ruling on the RAW-vs-corpus divergence).
    #[test]
    fn shaman_and_witch_share_one_familiar_implementation() {
        for class_id in ["class:witch", "class:shaman"] {
            let mut input = character(class_id, 5);
            input.chosen.selected_choices.push(SelectedChoice {
                choice_set_id: super::FAMILIAR_CHOICE_ID.to_owned(),
                selection_id: super::FAMILIAR_TOAD_SELECTION.to_owned(),
            });
            assert_eq!(
                value(&input, "class_feature.familiar.master_hit_point_bonus"),
                Some(3),
                "{class_id} must get the same familiar benefit"
            );
            assert_eq!(super::character_familiar_hp_bonus(&input), 3, "{class_id} HP bonus");
        }
    }

    /// The bonus reaching a real max-HP total is the whole reason Toad
    /// was picked as canonical, so the consumer-facing helper is
    /// differenced directly rather than trusted via the record.
    #[test]
    fn the_consumer_helper_reports_zero_without_a_familiar_and_three_with_one() {
        let bare = character("class:witch", 5);
        assert_eq!(super::character_familiar_hp_bonus(&bare), 0);

        let mut bonded = bare.clone();
        bonded.chosen.selected_choices.push(SelectedChoice {
            choice_set_id: super::FAMILIAR_CHOICE_ID.to_owned(),
            selection_id: super::FAMILIAR_TOAD_SELECTION.to_owned(),
        });
        assert_eq!(super::character_familiar_hp_bonus(&bonded) - super::character_familiar_hp_bonus(&bare), 3);
    }

    /// Slayer's talent count: `SlayerLVL/2` -- one at 2nd, ten by 20th.
    ///
    /// Ten `-1` deductions against this pool exist in the corpus, each
    /// gated on a `Slayer_CF_TalentN` flag whose only setters are Slayer
    /// ARCHETYPE `.MOD` records (Bounty Hunter, Cleaner, Cutthroat, and
    /// others). This repo ingests only the base `slayer.json`, so all
    /// ten are provably vacuous -- the same check that cleared Brawler's
    /// seven and Cavalier's three.
    #[test]
    fn slayer_talent_count_matches_the_corpus_and_ignores_archetype_deductions() {
        for (level, want) in [(1u8, 0i16), (2, 1), (3, 1), (4, 2), (10, 5), (19, 9), (20, 10)] {
            assert_eq!(super::slayer_talent_count(level), want, "level {level}");
        }
        assert_eq!(
            value(&character(SLAYER_CLASS_ID, 1), "class_feature.acg.slayer.talent_count"),
            None,
            "a level-1 Slayer has no talents yet"
        );
        assert_eq!(
            value(&character(SLAYER_CLASS_ID, 6), "class_feature.acg.slayer.talent_count"),
            Some(3)
        );
    }

    /// Foil Scrutiny is the one canonical talent grounded, narrowed the
    /// same way Order of the Sword and Animal Focus's Bull were. It
    /// requires an explicit recorded pick: a talent chooser's entire
    /// value IS which talent was taken, so seeding one would assert a
    /// specific checkable falsehood, per the ratified Skill Focus line.
    #[test]
    fn foil_scrutiny_grounds_only_when_explicitly_chosen() {
        let bare = character(SLAYER_CLASS_ID, 6);
        assert_eq!(
            value(&bare, "class_feature.acg.slayer.talent.foil_scrutiny_bonus"),
            None,
            "no talent is seeded"
        );

        let mut chosen = bare.clone();
        chosen.chosen.selected_choices.push(SelectedChoice {
            choice_set_id: super::SLAYER_TALENT_CHOICE_ID.to_owned(),
            selection_id: super::SLAYER_TALENT_FOIL_SCRUTINY_SELECTION.to_owned(),
        });
        assert_eq!(
            value(&chosen, "class_feature.acg.slayer.talent.foil_scrutiny_bonus"),
            Some(2)
        );
    }

    /// A talent cannot be held before any talent exists to spend.
    #[test]
    fn a_talent_choice_grounds_nothing_before_the_first_talent_is_gained() {
        let mut too_early = character(SLAYER_CLASS_ID, 1);
        too_early.chosen.selected_choices.push(SelectedChoice {
            choice_set_id: super::SLAYER_TALENT_CHOICE_ID.to_owned(),
            selection_id: super::SLAYER_TALENT_FOIL_SCRUTINY_SELECTION.to_owned(),
        });
        assert_eq!(
            value(&too_early, "class_feature.acg.slayer.talent.foil_scrutiny_bonus"),
            None,
            "a level-1 Slayer has no talent slot to have spent"
        );
    }

    /// Studied Combat's insight bonus is `InvestigatorLVL/2`, and its
    /// duration `max(1, INT)` rounds grounds as a fact but is explicitly
    /// UNENFORCED -- this engine has no round clock.
    #[test]
    fn investigator_studied_combat_grounds_its_bonus_and_an_unenforced_duration() {
        for (level, want) in [(1u8, 0i16), (2, 1), (7, 3), (20, 10)] {
            assert_eq!(super::investigator_studied_combat_bonus(level), want, "level {level}");
        }
        // Fixture INT 10 -> modifier 0 -> duration max(1, 0) = 1.
        assert_eq!(super::investigator_studied_combat_duration(0), 1);
        assert_eq!(super::investigator_studied_combat_duration(4), 4);

        let input = character(INVESTIGATOR_CLASS_ID, 6);
        assert_eq!(value(&input, "class_feature.acg.investigator.studied_combat_bonus"), Some(3));
        let duration = build_pilot_headless_receipt(&input)
            .computation
            .explanations
            .into_iter()
            .find(|e| e.id == "class_feature.acg.investigator.studied_combat_duration")
            .expect("duration must ground");
        assert!(
            duration.detail.to_lowercase().contains("not enforced"),
            "the duration must be named as unenforced: {duration:?}"
        );
    }

    /// Studied Strike: `min(9, (level-2)/2)` d6, genuinely absent below
    /// 4th and reaching 9d6 at 20th.
    ///
    /// Note the corpus clamp is NOT meaningfully covered here and cannot
    /// be: `(20-2)/2` is already exactly 9 and Rust's truncating
    /// division keeps the low end at 0, so neither bound ever binds.
    /// Asserting the reachable values is the most this test can honestly
    /// do -- the same limit as Brawler's Flurry cap.
    #[test]
    fn investigator_studied_strike_dice_cap_at_nine_and_start_at_fourth() {
        for level in 1..4u8 {
            assert_eq!(super::investigator_studied_strike_dice(level), 0, "level {level}");
        }
        for (level, want) in [(4u8, 1i16), (6, 2), (12, 5), (19, 8), (20, 9)] {
            assert_eq!(super::investigator_studied_strike_dice(level), want, "level {level}");
        }
        assert_eq!(value(&character(INVESTIGATOR_CLASS_ID, 1), "class_feature.acg.investigator.studied_strike_dice"), None);
        assert_eq!(value(&character(INVESTIGATOR_CLASS_ID, 6), "class_feature.acg.investigator.studied_strike_dice"), Some(2));
    }

    /// Studied Defense is a mechanism-B explicit choice: it redirects
    /// the SAME magnitude from attack rolls to AC. One magnitude, two
    /// destinations, player's pick -- never a silently seeded default.
    #[test]
    fn studied_defense_redirects_the_bonus_only_when_explicitly_chosen() {
        let without = character(INVESTIGATOR_CLASS_ID, 10);
        assert_eq!(
            value(&without, "class_feature.acg.investigator.studied_defense_ac_bonus"),
            None,
            "nothing is seeded without an explicit choice"
        );

        let mut with = without.clone();
        with.chosen.selected_choices.push(SelectedChoice {
            choice_set_id: INVESTIGATOR_STUDIED_DEFENSE_CHOICE_ID.to_owned(),
            selection_id: INVESTIGATOR_STUDIED_DEFENSE_SELECTION.to_owned(),
        });
        // Level 10 -> bonus 5, redirected to AC.
        assert_eq!(value(&with, "class_feature.acg.investigator.studied_defense_ac_bonus"), Some(5));
    }

    /// The talent gate is real: Studied Defense requires
    /// `InvestigatorTalentLVL >= 9`, and that variable IS properly set
    /// from `InvestigatorLVL` (unlike Swashbuckler's deed gate, which is
    /// never set -- checked tree-wide rather than assumed by analogy).
    #[test]
    fn studied_defense_respects_its_ninth_level_talent_gate() {
        let mut early = character(INVESTIGATOR_CLASS_ID, 8);
        early.chosen.selected_choices.push(SelectedChoice {
            choice_set_id: INVESTIGATOR_STUDIED_DEFENSE_CHOICE_ID.to_owned(),
            selection_id: INVESTIGATOR_STUDIED_DEFENSE_SELECTION.to_owned(),
        });
        assert_eq!(
            value(&early, "class_feature.acg.investigator.studied_defense_ac_bonus"),
            None,
            "the talent is not available below investigator level 9"
        );
    }

    /// Cavalier's Challenge grants `+CavalierLVL` damage against the
    /// challenge target, and it applies only while actually challenging.
    #[test]
    fn cavalier_challenge_damage_grounds_only_while_challenging() {
        let idle = character(CAVALIER_CLASS_ID, 1);
        assert_eq!(value(&idle, "class_feature.apg.cavalier.challenge_damage_bonus"), None);

        let mut challenging = idle.clone();
        challenging.chosen.class_ability_activations.push(ClassAbilityActivation {
            ability_id: CAVALIER_CHALLENGE_ABILITY_ID.to_owned(),
            active_state: ActiveState::EquippedActive,
            rounds_consumed_today: None,
        });
        assert_eq!(
            value(&challenging, "class_feature.apg.cavalier.challenge_damage_bonus"),
            Some(1)
        );
    }

    /// The two Challenge scopes are INVERSE and must not be conflated:
    /// the damage bonus applies ONLY against the challenge target, while
    /// the -2 AC penalty applies against everyone EXCEPT that target.
    #[test]
    fn the_two_challenge_scopes_are_described_as_inverses_not_conflated() {
        let mut challenging = character(CAVALIER_CLASS_ID, 1);
        challenging.chosen.class_ability_activations.push(ClassAbilityActivation {
            ability_id: CAVALIER_CHALLENGE_ABILITY_ID.to_owned(),
            active_state: ActiveState::EquippedActive,
            rounds_consumed_today: None,
        });
        let receipt = build_pilot_headless_receipt(&challenging);
        let find = |id: &str| {
            receipt.computation.explanations.iter().find(|e| e.id == id).cloned()
        };
        let damage = find("class_feature.apg.cavalier.challenge_damage_bonus").expect("damage");
        let penalty =
            find("class_feature.apg.cavalier.challenge_armor_class_penalty").expect("penalty");
        assert!(
            damage.detail.to_lowercase().contains("against the target"),
            "damage is scoped TO the target: {damage:?}"
        );
        assert!(
            penalty.detail.to_lowercase().contains("except against"),
            "the AC penalty is scoped to everyone EXCEPT the target: {penalty:?}"
        );
    }
}
